insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f2000000-0000-0000-0000-000000000001', 'mrcp1', 'a41601f9-ee4b-4ae5-a5cb-e736b267cd7d',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f2000000-0000-0000-0000-000000000001', 'A', 'Osteoarthritis', false, 'Ruled out because osteoarthritis typically causes minimal morning stiffness (under 30 minutes), favours the distal interphalangeal and first carpometacarpal joints, and is not associated with positive rheumatoid factor or anti-CCP antibodies.', 1),
('f2000000-0000-0000-0000-000000000001', 'B', 'Psoriatic arthritis', false, 'Ruled out because although psoriatic arthritis can cause a symmetrical polyarthritis, it is typically seronegative (rheumatoid factor and anti-CCP negative), and there is no mention of psoriasis or nail changes here.', 2),
('f2000000-0000-0000-0000-000000000001', 'C', 'Gout', false, 'Ruled out because gout typically causes acute monoarthritis (classically the first metatarsophalangeal joint), not chronic symmetrical small joint polyarthritis with positive anti-CCP antibodies.', 3),
('f2000000-0000-0000-0000-000000000001', 'D', 'Systemic lupus erythematosus', false, 'Ruled out because although SLE can cause arthralgia/arthritis, the specific pattern of erosive, anti-CCP-positive symmetrical small joint synovitis described here is most characteristic of rheumatoid arthritis.', 4),
('f2000000-0000-0000-0000-000000000001', 'E', 'Rheumatoid arthritis', true, 'Correct. Symmetrical small joint synovitis with prolonged morning stiffness, involvement of the MCP and PIP joints (sparing the distal interphalangeal joints), and positive rheumatoid factor and anti-CCP antibodies together are characteristic of rheumatoid arthritis.', 5),
('f2000000-0000-0000-0000-000000000002', 'A', 'Methotrexate', true, 'Correct. Methotrexate, the first-line DMARD for rheumatoid arthritis, requires regular monitoring of full blood count and liver function due to risks of bone marrow suppression and hepatotoxicity, and carries a recognised (though less common) risk of pneumonitis; folic acid is co-prescribed to reduce some side effects.', 1),
('f2000000-0000-0000-0000-000000000002', 'B', 'Hydroxychloroquine', false, $x$Ruled out because hydroxychloroquine's main monitoring concern is retinal toxicity (requiring regular ophthalmological screening), not the bone marrow suppression, hepatotoxicity and pneumonitis risk profile described here.$x$, 2),
('f2000000-0000-0000-0000-000000000002', 'C', 'Sulfasalazine', false, 'Ruled out because although sulfasalazine can rarely cause blood dyscrasias, it does not have the same characteristic risk profile (particularly pneumonitis) as classically associated with methotrexate.', 3),
('f2000000-0000-0000-0000-000000000002', 'D', 'Naproxen', false, 'Ruled out because naproxen is an NSAID, not a DMARD, and its main monitoring concerns are gastrointestinal and renal, not the specific triad of hepatotoxicity, bone marrow suppression and pneumonitis described.', 4),
('f2000000-0000-0000-0000-000000000002', 'E', 'Paracetamol', false, 'Ruled out because paracetamol is a simple analgesic with no disease-modifying effect and does not require this type of monitoring.', 5),
('f2000000-0000-0000-0000-000000000003', 'A', 'Cervical disc herniation from degenerative disease', false, 'Ruled out because simple degenerative disc disease does not typically cause this specific pattern of transient tetraplegia with neck movement in a patient with longstanding rheumatoid arthritis; the joint instability described is specifically due to RA-related ligamentous damage.', 1),
('f2000000-0000-0000-0000-000000000003', 'B', 'Vertebral artery dissection', false, 'Ruled out because this would present with posterior circulation stroke symptoms, not the pattern of transient tetraplegia related to neck movement and atlantoaxial subluxation described here.', 2),
('f2000000-0000-0000-0000-000000000003', 'C', 'Atlantoaxial subluxation from rheumatoid destruction of the transverse ligament', true, 'Correct. Chronic synovitis in rheumatoid arthritis can erode the transverse ligament stabilising the atlantoaxial joint, leading to subluxation; neck movement (e.g. during intubation) can then cause spinal cord compression, producing acute neurological compromise, which is why cervical spine assessment is important before procedures involving neck manipulation in longstanding RA.', 3),
('f2000000-0000-0000-0000-000000000003', 'D', 'Cervical spondylotic myelopathy from unrelated osteoarthritis', false, 'Ruled out because although cervical myelopathy can occur from degenerative disease, the specific finding of atlantoaxial subluxation in the context of longstanding rheumatoid arthritis points to RA-related ligamentous erosion as the cause.', 4),
('f2000000-0000-0000-0000-000000000003', 'E', 'Simple whiplash injury', false, 'Ruled out because there is no history of significant trauma, and the imaging finding of atlantoaxial subluxation in a patient with longstanding RA points to a chronic, disease-related process rather than an acute traumatic injury.', 5),
('f2000000-0000-0000-0000-000000000004', 'A', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis typically causes symmetrical small joint synovitis without dactylitis or the specific nail changes seen in psoriatic disease.', 1),
('f2000000-0000-0000-0000-000000000004', 'B', 'Psoriatic arthritis', true, $x$Correct. Dactylitis (diffuse swelling of an entire digit, giving a 'sausage finger' appearance) combined with nail pitting in a patient with known psoriasis is characteristic of psoriatic arthritis, reflecting combined synovial, tendon sheath and entheseal inflammation.$x$, 2),
('f2000000-0000-0000-0000-000000000004', 'C', 'Gout', false, 'Ruled out because gout typically causes acute monoarthritis, most classically of the first metatarsophalangeal joint, not dactylitis of a finger with nail pitting.', 3),
('f2000000-0000-0000-0000-000000000004', 'D', 'Osteoarthritis', false, $x$Ruled out because osteoarthritis does not cause dactylitis (diffuse whole-digit swelling); it more typically causes localised joint changes such as Heberden's and Bouchard's nodes.$x$, 4),
('f2000000-0000-0000-0000-000000000004', 'E', 'Reactive arthritis', false, 'Ruled out because reactive arthritis typically follows a specific infective trigger (GI or GU infection) and is not linked to nail pitting from underlying psoriasis, which specifically points to psoriatic arthritis here.', 5),
('f2000000-0000-0000-0000-000000000005', 'A', 'Gonococcal septic arthritis', false, 'Ruled out because although gonorrhoea can cause a septic arthritis with associated urethritis, it would not typically cause conjunctivitis as part of the same triad; the specific combination described is classic for reactive arthritis.', 1),
('f2000000-0000-0000-0000-000000000005', 'B', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis is a chronic, symmetrical small joint polyarthritis, not this acute, asymmetrical oligoarthritis following a specific infective trigger with conjunctivitis and urethritis.', 2),
('f2000000-0000-0000-0000-000000000005', 'C', 'Psoriatic arthritis', false, 'Ruled out because there is no mention of psoriasis, and the specific triad of conjunctivitis, urethritis and post-infective oligoarthritis points to reactive arthritis instead.', 3),
('f2000000-0000-0000-0000-000000000005', 'D', 'Reactive arthritis', true, 'Correct. The triad of conjunctivitis, urethritis and asymmetrical oligoarthritis occurring after a genitourinary (or gastrointestinal) infection is classic for reactive arthritis, an immune-mediated arthritis triggered by, but not directly caused by ongoing infection with, organisms such as Chlamydia trachomatis.', 4),
('f2000000-0000-0000-0000-000000000005', 'E', 'Ankylosing spondylitis', false, 'Ruled out because ankylosing spondylitis typically presents with chronic inflammatory back pain and progressive spinal involvement, not this acute post-infective triad affecting peripheral joints and eyes.', 5),
('f2000000-0000-0000-0000-000000000006', 'A', 'Methotrexate-induced pneumonitis alone, unrelated to rheumatoid arthritis', false, 'Ruled out because although methotrexate pneumonitis is an important differential, it typically presents more acutely and with a different (often more ground-glass, hypersensitivity-type) pattern, whereas the chronic, fibrotic, basal-predominant honeycombing pattern described is more typical of rheumatoid-associated interstitial lung disease itself.', 1),
('f2000000-0000-0000-0000-000000000006', 'B', 'Simple community-acquired pneumonia', false, 'Ruled out because the chronic, progressive course over months with a fibrotic HRCT pattern is not consistent with an acute infective pneumonia.', 2),
('f2000000-0000-0000-0000-000000000006', 'C', 'Pulmonary embolism', false, 'Ruled out because PE would not produce this chronic, progressive fibrotic HRCT pattern; it would present more acutely, typically without the basal reticulation and honeycombing described.', 3),
('f2000000-0000-0000-0000-000000000006', 'D', 'Rheumatoid arthritis-associated interstitial lung disease', true, 'Correct. Progressive breathlessness and dry cough with a usual interstitial pneumonia-like pattern on HRCT (basal-predominant reticulation with honeycombing) is a recognised extra-articular pulmonary manifestation of rheumatoid arthritis, though methotrexate-induced pneumonitis should also be considered and distinguished, as management differs.', 4),
('f2000000-0000-0000-0000-000000000006', 'E', 'Asthma', false, 'Ruled out because asthma causes reversible airway obstruction with wheeze, not this progressive fibrotic interstitial pattern on imaging.', 5),
('f2000000-0000-0000-0000-000000000007', 'A', 'Mechanical low back pain', false, 'Ruled out because mechanical back pain is typically worse with activity and improves with rest, the opposite pattern to the inflammatory back pain described here, and would not be associated with sacroiliitis or HLA-B27 positivity.', 1),
('f2000000-0000-0000-0000-000000000007', 'B', 'Ankylosing spondylitis', true, 'Correct. Chronic inflammatory back pain (morning stiffness improving with exercise, worse with rest) in a young man, with reduced spinal mobility, sacroiliitis on imaging, and HLA-B27 positivity, is characteristic of ankylosing spondylitis, a seronegative spondyloarthropathy.', 2),
('f2000000-0000-0000-0000-000000000007', 'C', 'Lumbar disc herniation', false, 'Ruled out because disc herniation typically causes radicular leg pain with a mechanical pattern, not the inflammatory pattern (morning stiffness improving with exercise) and sacroiliitis described here.', 3),
('f2000000-0000-0000-0000-000000000007', 'D', 'Osteoarthritis of the spine', false, 'Ruled out because osteoarthritis causes mechanical, activity-related pain in older patients, not the inflammatory pattern in a young man with sacroiliitis and HLA-B27 positivity.', 4),
('f2000000-0000-0000-0000-000000000007', 'E', 'Fibromyalgia', false, 'Ruled out because fibromyalgia causes widespread chronic pain without objective inflammatory findings such as sacroiliitis on imaging.', 5),
('f2000000-0000-0000-0000-000000000008', 'A', 'Add a fourth conventional synthetic DMARD to the existing three', false, 'Ruled out because further combination of conventional synthetic DMARDs beyond an adequate trial is not the standard next step when disease activity remains significant; escalation to a biologic agent is indicated instead.', 1),
('f2000000-0000-0000-0000-000000000008', 'B', 'Stop all DMARDs and manage with analgesia alone', false, 'Ruled out because stopping disease-modifying treatment in active rheumatoid arthritis would allow ongoing joint damage; escalation, not withdrawal, of treatment is needed.', 2),
('f2000000-0000-0000-0000-000000000008', 'C', 'Add a biologic DMARD, such as a TNF-alpha inhibitor', true, 'Correct. In rheumatoid arthritis with ongoing significant disease activity despite an adequate trial of combination conventional synthetic DMARDs, escalation to a biologic DMARD (such as a TNF-alpha inhibitor) is the recommended next step to achieve better disease control.', 3),
('f2000000-0000-0000-0000-000000000008', 'D', 'Increase the dose of oral corticosteroids as long-term maintenance therapy', false, 'Ruled out because long-term high-dose corticosteroids are not appropriate maintenance therapy due to cumulative toxicity; they may be used short-term as a bridge, but biologic therapy is the appropriate escalation step for ongoing disease control.', 4),
('f2000000-0000-0000-0000-000000000008', 'E', 'Refer for joint replacement surgery', false, 'Ruled out because surgery is considered for structural joint damage causing significant functional impairment, not as the response to ongoing inflammatory disease activity that has not yet been adequately controlled medically.', 5),
('f2000000-0000-0000-0000-000000000009', 'A', 'AA (secondary) amyloidosis', true, 'Correct. Chronic, longstanding inflammatory disease (such as rheumatoid arthritis) can lead to secondary (AA) amyloidosis, in which persistently elevated serum amyloid A protein deposits in tissues including the kidney, causing proteinuria; Congo red staining with apple-green birefringence confirms amyloid deposition.', 1),
('f2000000-0000-0000-0000-000000000009', 'B', 'Diabetic nephropathy', false, 'Ruled out because there is no mention of diabetes, and the specific finding of Congo red-positive amyloid deposits points to amyloidosis, not diabetic glomerular changes.', 2),
('f2000000-0000-0000-0000-000000000009', 'C', 'Minimal change disease', false, 'Ruled out because minimal change disease does not show amyloid deposits on Congo red staining; the biopsy finding described is specific to amyloidosis.', 3),
('f2000000-0000-0000-0000-000000000009', 'D', 'Membranous nephropathy', false, 'Ruled out because membranous nephropathy shows a different histological pattern (subepithelial immune deposits), not Congo red-positive amyloid with apple-green birefringence.', 4),
('f2000000-0000-0000-0000-000000000009', 'E', 'AL (primary) amyloidosis', false, 'Ruled out because AL amyloidosis arises from a plasma cell dyscrasia producing abnormal light chains, not from chronic inflammatory disease; the strong context of longstanding rheumatoid arthritis points specifically to AA (secondary) amyloidosis.', 5),
('f2000000-0000-0000-0000-000000000010', 'A', 'Simple age-related dry eyes and dry mouth', false, $x$Ruled out because the positive Schirmer's test combined with specific autoantibodies (anti-Ro, anti-La) indicates an autoimmune cause, not simply age-related changes.$x$, 1),
('f2000000-0000-0000-0000-000000000010', 'B', 'Sarcoidosis', false, 'Ruled out because although sarcoidosis can rarely cause sicca-like symptoms via granulomatous gland infiltration, the specific serological findings (anti-Ro, anti-La) and the context of underlying rheumatoid arthritis are classic for Sjogren syndrome instead.', 2),
('f2000000-0000-0000-0000-000000000010', 'C', 'Diabetes insipidus', false, 'Ruled out because diabetes insipidus causes polyuria and polydipsia from an ADH abnormality, not dry eyes and dry mouth from exocrine gland dysfunction with positive Sjogren-specific antibodies.', 3),
('f2000000-0000-0000-0000-000000000010', 'D', 'Medication side effect alone, unrelated to autoimmune disease', false, $x$Ruled out because although some medications can cause dry mouth, the positive Schirmer's test and specific autoantibody profile point to an underlying autoimmune sicca syndrome rather than a simple drug effect.$x$, 4),
('f2000000-0000-0000-0000-000000000010', 'E', 'Secondary Sjogren syndrome', true, $x$Correct. Sicca symptoms (dry eyes, dry mouth) with a positive Schirmer's test and positive anti-Ro/anti-La antibodies occurring in a patient with an established underlying autoimmune disease (rheumatoid arthritis) define secondary Sjogren syndrome, an autoimmune exocrinopathy affecting lacrimal and salivary glands.$x$, 5),
('f2000000-0000-0000-0000-000000000011', 'A', 'Dermatomyositis', false, $x$Ruled out because dermatomyositis causes a heliotrope rash and Gottron's papules with proximal muscle weakness, not the specific malar rash pattern and anti-dsDNA positivity described here.$x$, 1),
('f2000000-0000-0000-0000-000000000011', 'B', 'Systemic lupus erythematosus', true, 'Correct. A photosensitive malar rash, arthralgia, oral ulcers, positive ANA and anti-dsDNA antibodies, and low complement levels (reflecting complement consumption from immune complex activity) together fulfil clinical and serological criteria for systemic lupus erythematosus.', 2),
('f2000000-0000-0000-0000-000000000011', 'C', 'Rosacea', false, 'Ruled out because rosacea causes facial erythema but does not spare the nasolabial folds in the same pattern, is not photosensitive in this way, and would not be associated with anti-dsDNA antibodies or low complement.', 3),
('f2000000-0000-0000-0000-000000000011', 'D', 'Systemic sclerosis', false, $x$Ruled out because systemic sclerosis causes skin thickening and Raynaud's phenomenon, not this specific malar rash and anti-dsDNA antibody pattern.$x$, 4),
('f2000000-0000-0000-0000-000000000011', 'E', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis does not cause a malar rash or oral ulcers, and is associated with rheumatoid factor/anti-CCP rather than anti-dsDNA antibodies.', 5),
('f2000000-0000-0000-0000-000000000012', 'A', 'Lupus nephritis', true, 'Correct. Proteinuria, red cell casts, oedema and hypertension in a patient with known SLE reflect immune complex-mediated glomerulonephritis (lupus nephritis), a major and potentially serious renal complication requiring prompt investigation (often renal biopsy) and treatment to prevent progressive kidney damage.', 1),
('f2000000-0000-0000-0000-000000000012', 'B', 'Diabetic nephropathy', false, 'Ruled out because there is no mention of diabetes, and the acute nephritic picture with red cell casts in a patient with known SLE points specifically to lupus nephritis.', 2),
('f2000000-0000-0000-0000-000000000012', 'C', 'Minimal change disease unrelated to SLE', false, 'Ruled out because minimal change disease typically presents with a nephrotic picture without red cell casts, and the strong clinical context of known SLE points to lupus nephritis as the more likely diagnosis.', 3),
('f2000000-0000-0000-0000-000000000012', 'D', 'Urinary tract infection', false, 'Ruled out because a UTI would not typically cause significant proteinuria with red cell casts, which reflect a glomerular, not infective lower urinary tract, process.', 4),
('f2000000-0000-0000-0000-000000000012', 'E', 'Pre-eclampsia', false, 'Ruled out because there is no mention of pregnancy, and the clinical context of known SLE with red cell casts points specifically to lupus nephritis.', 5),
('f2000000-0000-0000-0000-000000000013', 'A', 'Systemic lupus erythematosus', false, $x$Ruled out because SLE does not cause skin thickening (sclerodactyly) or the specific combination of Raynaud's, telangiectasia and oesophageal dysmotility described here.$x$, 1),
('f2000000-0000-0000-0000-000000000013', 'B', 'Dermatomyositis', false, 'Ruled out because dermatomyositis causes a heliotrope rash and proximal muscle weakness, not skin thickening (sclerodactyly) and the CREST-type features described.', 2),
('f2000000-0000-0000-0000-000000000013', 'C', 'Mixed connective tissue disease', false, $x$Ruled out because although MCTD shares some overlapping features, the specific, classic combination of sclerodactyly, Raynaud's, telangiectasia and oesophageal involvement is most characteristic of limited systemic sclerosis.$x$, 3),
('f2000000-0000-0000-0000-000000000013', 'D', $x$Raynaud's phenomenon alone (primary)$x$, false, $x$Ruled out because primary Raynaud's occurs in isolation without skin thickening, telangiectasia or oesophageal involvement; the additional features described indicate an underlying secondary connective tissue disease.$x$, 4),
('f2000000-0000-0000-0000-000000000013', 'E', 'Systemic sclerosis (limited cutaneous form)', true, $x$Correct. Skin thickening confined to the fingers, face and distal limbs (sclerodactyly), Raynaud's phenomenon, telangiectasia and oesophageal dysmotility (dysphagia) are characteristic of limited cutaneous systemic sclerosis, historically also described using the CREST acronym.$x$, 5),
('f2000000-0000-0000-0000-000000000014', 'A', 'Simple essential hypertension', false, 'Ruled out because the abrupt, severe onset in a patient with diffuse systemic sclerosis, combined with acute kidney injury, points to a specific disease complication (scleroderma renal crisis) rather than chronic essential hypertension.', 1),
('f2000000-0000-0000-0000-000000000014', 'B', 'Pre-eclampsia', false, 'Ruled out because there is no mention of pregnancy, and the clinical context (known diffuse systemic sclerosis) points specifically to scleroderma renal crisis.', 2),
('f2000000-0000-0000-0000-000000000014', 'C', 'Scleroderma renal crisis', true, 'Correct. Abrupt-onset severe hypertension with acute kidney injury in a patient with diffuse systemic sclerosis is characteristic of scleroderma renal crisis, a life-threatening complication caused by intrarenal vascular narrowing, requiring urgent treatment with an ACE inhibitor to control blood pressure and preserve renal function.', 3),
('f2000000-0000-0000-0000-000000000014', 'D', 'Phaeochromocytoma', false, 'Ruled out because although phaeochromocytoma causes severe hypertension, it does not have the specific association with diffuse systemic sclerosis and acute kidney injury seen in scleroderma renal crisis.', 4),
('f2000000-0000-0000-0000-000000000014', 'E', 'Chronic kidney disease progression', false, 'Ruled out because the abrupt, severe rise in blood pressure and acute (rather than gradual, chronic) rise in creatinine reflects an acute crisis, not simple progression of pre-existing chronic kidney disease.', 5),
('f2000000-0000-0000-0000-000000000015', 'A', 'Polymyositis', false, $x$Ruled out because polymyositis causes proximal muscle weakness with raised CK but, by definition, lacks the characteristic skin findings (heliotrope rash, Gottron's papules) that are present here and define dermatomyositis instead.$x$, 1),
('f2000000-0000-0000-0000-000000000015', 'B', 'Polymyalgia rheumatica', false, 'Ruled out because PMR causes proximal muscle pain and stiffness (typically without significant weakness or markedly raised CK) and does not cause the characteristic rash described.', 2),
('f2000000-0000-0000-0000-000000000015', 'C', 'Fibromyalgia', false, 'Ruled out because fibromyalgia causes widespread pain without objective muscle weakness, raised CK, or the specific cutaneous findings described.', 3),
('f2000000-0000-0000-0000-000000000015', 'D', 'Dermatomyositis', true, $x$Correct. Proximal muscle weakness with a markedly raised creatine kinase, combined with a heliotrope rash (violaceous discolouration of the upper eyelids) and Gottron's papules (scaly plaques over the knuckles), is characteristic of dermatomyositis, an inflammatory myopathy with distinctive cutaneous features.$x$, 4),
('f2000000-0000-0000-0000-000000000015', 'E', 'Hypothyroid myopathy', false, $x$Ruled out because although hypothyroidism can cause proximal myopathy with raised CK, it does not cause the specific heliotrope rash and Gottron's papules seen in dermatomyositis.$x$, 5),
('f2000000-0000-0000-0000-000000000016', 'A', 'Dermatomyositis is itself a form of cancer requiring staging', false, 'Ruled out because dermatomyositis is an autoimmune inflammatory myopathy, not a malignancy itself; screening is performed because of its association with a separate, underlying cancer, not because the condition itself is cancerous.', 1),
('f2000000-0000-0000-0000-000000000016', 'B', 'Dermatomyositis (particularly in adults) has a well-established association with underlying occult malignancy, which screening aims to detect', true, 'Correct. Adult-onset dermatomyositis carries a significantly increased risk of an underlying malignancy (particularly ovarian, lung, pancreatic, gastric and colorectal cancers, and lymphoma) around the time of diagnosis, making age- and risk-appropriate cancer screening an important part of the initial workup.', 2),
('f2000000-0000-0000-0000-000000000016', 'C', 'Screening is done purely to exclude an alternative diagnosis, with no link between the two conditions', false, 'Ruled out because there is a genuine, well-documented paraneoplastic-type association between dermatomyositis and malignancy, not simply diagnostic exclusion of an unrelated condition.', 3),
('f2000000-0000-0000-0000-000000000016', 'D', 'Immunosuppressive treatment for dermatomyositis directly causes cancer, requiring monitoring', false, 'Ruled out because although long-term immunosuppression carries some cancer risk over time, the specific, well-established association being screened for at diagnosis relates to an underlying occult malignancy linked to the dermatomyositis itself, not treatment-induced cancer at this early stage.', 4),
('f2000000-0000-0000-0000-000000000016', 'E', 'There is no genuine increased cancer risk; this is a historical practice with no current evidence base', false, 'Ruled out because the association between adult dermatomyositis and malignancy is well-supported by evidence and remains current standard practice guiding screening recommendations.', 5),
('f2000000-0000-0000-0000-000000000017', 'A', 'Factor V Leiden thrombophilia', false, 'Ruled out because although Factor V Leiden also causes a prothrombotic state, it would not explain the positive lupus anticoagulant and anticardiolipin antibody results, which are specific to antiphospholipid syndrome.', 1),
('f2000000-0000-0000-0000-000000000017', 'B', 'Protein C deficiency', false, 'Ruled out because protein C deficiency is a distinct inherited thrombophilia, not associated with positive lupus anticoagulant or anticardiolipin antibodies.', 2),
('f2000000-0000-0000-0000-000000000017', 'C', 'Antiphospholipid syndrome', true, 'Correct. Recurrent pregnancy loss and unprovoked venous thromboembolism, with persistently positive antiphospholipid antibodies (lupus anticoagulant and/or anticardiolipin antibodies) confirmed on repeat testing 12 weeks apart, fulfils clinical and laboratory criteria for antiphospholipid syndrome, a prothrombotic autoimmune condition.', 3),
('f2000000-0000-0000-0000-000000000017', 'D', 'Systemic lupus erythematosus alone, without antiphospholipid syndrome', false, 'Ruled out because although antiphospholipid syndrome can occur secondary to SLE, there is no other information here suggesting a separate SLE diagnosis (e.g. rash, arthritis, anti-dsDNA); the clinical and laboratory picture specifically fits (primary) antiphospholipid syndrome.', 4),
('f2000000-0000-0000-0000-000000000017', 'E', 'Simple sporadic miscarriage unrelated to a systemic condition', false, 'Ruled out because the combination of recurrent pregnancy loss, unprovoked VTE, and persistently positive specific antibodies indicates an underlying systemic prothrombotic autoimmune condition, not chance sporadic events.', 5),
('f2000000-0000-0000-0000-000000000018', 'A', 'Systemic lupus erythematosus', false, 'Ruled out because the negative anti-dsDNA antibody and the overlapping scleroderma/myositis features, together with the specific anti-U1-RNP positivity, favour mixed connective tissue disease over isolated SLE.', 1),
('f2000000-0000-0000-0000-000000000018', 'B', 'Systemic sclerosis alone', false, 'Ruled out because the negative anti-Scl-70 antibody and the additional overlapping lupus and myositis features point to mixed connective tissue disease rather than isolated systemic sclerosis.', 2),
('f2000000-0000-0000-0000-000000000018', 'C', 'Polymyositis alone', false, $x$Ruled out because polymyositis alone would not explain the rash, Raynaud's phenomenon and specific anti-U1-RNP serology, which together indicate an overlap syndrome.$x$, 3),
('f2000000-0000-0000-0000-000000000018', 'D', 'Rheumatoid arthritis', false, $x$Ruled out because rheumatoid arthritis does not cause Raynaud's phenomenon or myositis, and is not associated with anti-U1-RNP antibody positivity.$x$, 4),
('f2000000-0000-0000-0000-000000000018', 'E', 'Mixed connective tissue disease', true, $x$Correct. Overlapping features of SLE (arthralgia, rash), systemic sclerosis (Raynaud's, swollen fingers) and myositis (mild proximal weakness), with a high titre of anti-U1-RNP antibody and absence of the specific antibodies for isolated SLE (anti-dsDNA) or systemic sclerosis (anti-Scl-70), is characteristic of mixed connective tissue disease.$x$, 5),
('f2000000-0000-0000-0000-000000000019', 'A', 'Congenital complete heart block', true, 'Correct. Maternal anti-Ro (and anti-La) antibodies can cross the placenta and damage the fetal cardiac conduction system, causing congenital complete heart block, a serious complication of neonatal lupus syndrome that is monitored for with serial fetal echocardiography during pregnancy.', 1),
('f2000000-0000-0000-0000-000000000019', 'B', 'Neural tube defects', false, 'Ruled out because neural tube defects are associated with folate deficiency or certain teratogenic medications (e.g. sodium valproate, trimethoprim in early pregnancy), not specifically with maternal anti-Ro antibody transfer.', 2),
('f2000000-0000-0000-0000-000000000019', 'C', 'Congenital cataracts', false, 'Ruled out because congenital cataracts are classically associated with congenital rubella infection, not maternal anti-Ro antibody transfer.', 3),
('f2000000-0000-0000-0000-000000000019', 'D', 'Down syndrome (trisomy 21)', false, 'Ruled out because Down syndrome is a chromosomal abnormality unrelated to maternal autoantibody status; it is not a recognised consequence of anti-Ro antibody transfer.', 4),
('f2000000-0000-0000-0000-000000000019', 'E', 'Cleft palate', false, 'Ruled out because cleft palate is not a recognised specific complication of maternal anti-Ro antibody transfer; the well-established fetal risk from this antibody is cardiac conduction system damage.', 5),
('f2000000-0000-0000-0000-000000000020', 'A', 'Regular use of sunscreen', false, 'Ruled out because sunscreen use reduces, rather than triggers, UV-related flares, and is a recommended protective measure for patients with SLE, not a precipitant.', 1),
('f2000000-0000-0000-0000-000000000020', 'B', 'Continuing hydroxychloroquine as prescribed', false, 'Ruled out because hydroxychloroquine is a maintenance treatment for SLE that helps prevent flares, not a trigger for them.', 2),
('f2000000-0000-0000-0000-000000000020', 'C', 'Adequate sleep and rest', false, 'Ruled out because adequate rest is generally beneficial for patients with chronic autoimmune disease and is not a recognised flare trigger; the relevant precipitant in this scenario is sun exposure.', 3),
('f2000000-0000-0000-0000-000000000020', 'D', 'UV light exposure', true, 'Correct. Ultraviolet light exposure is a well-recognised trigger for SLE flares, inducing keratinocyte apoptosis and exposure of nuclear antigens that provoke an autoimmune inflammatory response, explaining the photosensitive nature of lupus rashes and disease flares following sun exposure.', 4),
('f2000000-0000-0000-0000-000000000020', 'E', 'Regular moderate exercise', false, 'Ruled out because moderate exercise is generally encouraged as part of overall management in stable SLE and is not itself a recognised trigger for disease flares.', 5),
('f2000000-0000-0000-0000-000000000021', 'A', 'Takayasu arteritis', false, 'Ruled out because Takayasu arteritis typically affects younger patients (under 40) and involves the aorta and its major branches, not the temporal artery pattern with jaw claudication seen here.', 1),
('f2000000-0000-0000-0000-000000000021', 'B', 'Giant cell arteritis', true, 'Correct. New temporal headache, scalp tenderness, jaw claudication, a markedly raised ESR, and granulomatous inflammation with giant cells on temporal artery biopsy together confirm giant cell arteritis, a large/medium vessel vasculitis predominantly affecting older adults.', 2),
('f2000000-0000-0000-0000-000000000021', 'C', 'Polyarteritis nodosa', false, 'Ruled out because PAN is a medium-vessel vasculitis typically causing multisystem involvement (renal, GI, skin, neurological) without the specific temporal artery granulomatous biopsy finding described.', 3),
('f2000000-0000-0000-0000-000000000021', 'D', 'Granulomatosis with polyangiitis', false, 'Ruled out because GPA classically involves the upper and lower respiratory tract and kidneys with ANCA positivity, not this specific temporal artery pattern.', 4),
('f2000000-0000-0000-0000-000000000021', 'E', 'Migraine', false, 'Ruled out because migraine does not cause jaw claudication, a raised ESR, or granulomatous changes on temporal artery biopsy.', 5),
('f2000000-0000-0000-0000-000000000022', 'A', 'Central retinal vein occlusion', false, $x$Ruled out because CRVO typically causes a 'blood and thunder' fundal appearance with widespread haemorrhages, not the pale, swollen disc described, which is specific to ischaemic optic neuropathy.$x$, 1),
('f2000000-0000-0000-0000-000000000022', 'B', 'Retinal detachment', false, 'Ruled out because retinal detachment causes a curtain-like visual field loss with a specific fundal appearance of the detached retina, not the pale, swollen optic disc described here.', 2),
('f2000000-0000-0000-0000-000000000022', 'C', 'Anterior ischaemic optic neuropathy', true, 'Correct. Sudden painless visual loss with a pale, swollen optic disc in a patient with giant cell arteritis reflects arteritic anterior ischaemic optic neuropathy, caused by occlusion of the posterior ciliary arteries supplying the optic nerve head; this is a vision- and often irreversible-threatening emergency requiring urgent escalation of steroid treatment.', 3),
('f2000000-0000-0000-0000-000000000022', 'D', 'Vitreous haemorrhage', false, 'Ruled out because vitreous haemorrhage causes visual loss with a hazy or obscured fundal view from blood, not the specific pale, swollen disc appearance described.', 4),
('f2000000-0000-0000-0000-000000000022', 'E', 'Simple migraine-related visual disturbance', false, 'Ruled out because migraine visual disturbance is transient and does not cause a persistent pale, swollen optic disc; this finding indicates a structural ischaemic event requiring urgent treatment.', 5),
('f2000000-0000-0000-0000-000000000023', 'A', 'Microscopic polyangiitis', false, 'Ruled out because microscopic polyangiitis is typically p-ANCA (anti-MPO) positive and does not cause the granulomatous upper respiratory tract and cavitating lung nodule features seen in GPA.', 1),
('f2000000-0000-0000-0000-000000000023', 'B', 'Eosinophilic granulomatosis with polyangiitis (Churg-Strauss)', false, $x$Ruled out because EGPA is characterised by asthma and marked eosinophilia, features not described here, and this patient's serology and pattern more closely fit GPA.$x$, 2),
('f2000000-0000-0000-0000-000000000023', 'C', 'Goodpasture syndrome (anti-GBM disease)', false, 'Ruled out because anti-GBM disease is caused by antibodies against the glomerular and alveolar basement membrane, not ANCA, and does not classically cause cavitating nodules or nasal crusting.', 3),
('f2000000-0000-0000-0000-000000000023', 'D', 'Granulomatosis with polyangiitis', true, 'Correct. Upper respiratory tract involvement (nasal crusting, epistaxis, sinusitis), lower respiratory tract involvement (cavitating pulmonary nodules, haemoptysis), renal involvement (haematuria), and strongly positive c-ANCA (anti-PR3) together are characteristic of granulomatosis with polyangiitis, a small-vessel ANCA-associated vasculitis.', 4),
('f2000000-0000-0000-0000-000000000023', 'E', 'Pulmonary tuberculosis', false, 'Ruled out because although TB can cause cavitating lung lesions, it would not explain the nasal crusting, epistaxis and positive c-ANCA, which together point specifically to GPA.', 5),
('f2000000-0000-0000-0000-000000000024', 'A', 'Eosinophilic granulomatosis with polyangiitis', true, 'Correct. A background of asthma and allergic rhinitis, marked peripheral eosinophilia, and new vasculitic features (peripheral neuropathy, purpuric rash) with p-ANCA positivity together are characteristic of eosinophilic granulomatosis with polyangiitis (formerly Churg-Strauss syndrome), a small-vessel ANCA-associated vasculitis with a distinctive eosinophilic and asthmatic prodrome.', 1),
('f2000000-0000-0000-0000-000000000024', 'B', 'Granulomatosis with polyangiitis', false, 'Ruled out because GPA is typically c-ANCA (anti-PR3) positive and does not have the characteristic preceding asthma/allergic rhinitis and marked eosinophilia seen in EGPA.', 2),
('f2000000-0000-0000-0000-000000000024', 'C', 'Microscopic polyangiitis', false, 'Ruled out because although MPA is also p-ANCA positive, it lacks the characteristic asthma history and marked eosinophilia that specifically define EGPA.', 3),
('f2000000-0000-0000-0000-000000000024', 'D', 'Polyarteritis nodosa', false, 'Ruled out because PAN is not associated with ANCA positivity or marked eosinophilia, and does not have the characteristic asthmatic prodrome seen in EGPA.', 4),
('f2000000-0000-0000-0000-000000000024', 'E', 'Hypereosinophilic syndrome alone, without vasculitis', false, 'Ruled out because the presence of vasculitic features (neuropathy, purpuric rash) with positive ANCA indicates a vasculitis, not simply an isolated eosinophilic disorder.', 5),
('f2000000-0000-0000-0000-000000000025', 'A', 'Scarlet fever', false, 'Ruled out because although scarlet fever also causes fever and rash, it does not cause coronary artery involvement, and is associated with a specific streptococcal sore throat rather than this multisystem mucocutaneous syndrome.', 1),
('f2000000-0000-0000-0000-000000000025', 'B', 'Measles', false, 'Ruled out because measles causes a different rash pattern with Koplik spots and typically a clear infective contact history, not the specific combination of coronary artery involvement and mucocutaneous features described here.', 2),
('f2000000-0000-0000-0000-000000000025', 'C', 'Toxic shock syndrome', false, 'Ruled out because although TSS can cause fever and rash, it typically presents with hypotension and multi-organ dysfunction from a specific toxin-producing infection, not this classic Kawasaki symptom complex with coronary involvement.', 3),
('f2000000-0000-0000-0000-000000000025', 'D', 'Juvenile idiopathic arthritis', false, 'Ruled out because JIA is a chronic arthritis, not an acute febrile vasculitic illness with the mucocutaneous features and coronary artery involvement described here.', 4),
('f2000000-0000-0000-0000-000000000025', 'E', 'Kawasaki disease', true, 'Correct. Prolonged fever with bilateral non-purulent conjunctivitis, a polymorphous rash, mucocutaneous changes (cracked lips), cervical lymphadenopathy, and coronary artery involvement on echocardiography are characteristic of Kawasaki disease, a medium-vessel vasculitis of childhood requiring prompt treatment with IVIG and aspirin to reduce the risk of coronary artery aneurysm.', 5),
('f2000000-0000-0000-0000-000000000026', 'A', 'Meningococcal septicaemia', false, 'Ruled out because although meningococcal disease also causes a purpuric rash, the child here is not septic/shocked, and the specific combination of abdominal pain, arthralgia and renal involvement following a recent URTI is classic for HSP rather than an acute bacteraemic illness.', 1),
('f2000000-0000-0000-0000-000000000026', 'B', 'Idiopathic thrombocytopenic purpura', false, 'Ruled out because ITP causes a purpuric rash from low platelets without the abdominal pain, arthralgia or renal involvement seen here, and platelet count is typically normal in HSP.', 2),
('f2000000-0000-0000-0000-000000000026', 'C', 'Haemolytic uraemic syndrome', false, 'Ruled out because HUS classically follows diarrhoeal illness (often E. coli O157) with the triad of haemolytic anaemia, thrombocytopenia and acute kidney injury, not this pattern of purpura, arthralgia and abdominal pain following a URTI.', 3),
('f2000000-0000-0000-0000-000000000026', 'D', 'Kawasaki disease', false, 'Ruled out because Kawasaki disease causes a different symptom complex (prolonged fever, conjunctivitis, mucosal changes, coronary involvement), not the palpable purpura and renal/GI/joint involvement described here.', 4),
('f2000000-0000-0000-0000-000000000026', 'E', 'Henoch-Schonlein purpura (IgA vasculitis)', true, 'Correct. Palpable purpura over dependent areas (buttocks, lower legs), abdominal pain, arthralgia and renal involvement (haematuria), following an upper respiratory tract infection in a child, is the classic tetrad of Henoch-Schonlein purpura, an IgA-mediated small-vessel vasculitis.', 5),
('f2000000-0000-0000-0000-000000000027', 'A', 'Granulomatosis with polyangiitis', false, 'Ruled out because GPA is typically ANCA-positive (c-ANCA/anti-PR3) and does not have the specific hepatitis B association or angiographic microaneurysm pattern seen in PAN.', 1),
('f2000000-0000-0000-0000-000000000027', 'B', 'Microscopic polyangiitis', false, 'Ruled out because MPA is typically p-ANCA (anti-MPO) positive and affects small vessels, causing glomerulonephritis and pulmonary capillaritis, not the medium-vessel microaneurysm pattern described here.', 2),
('f2000000-0000-0000-0000-000000000027', 'C', 'Takayasu arteritis', false, 'Ruled out because Takayasu arteritis affects the aorta and its major branches in younger patients, not the mesenteric/renal medium-vessel microaneurysm pattern with hepatitis B association described here.', 3),
('f2000000-0000-0000-0000-000000000027', 'D', 'Polyarteritis nodosa', true, 'Correct. Systemic symptoms with multi-organ involvement (renal, mesenteric, hypertension), ANCA-negative status, and microaneurysms on angiography, in a patient with chronic hepatitis B (a recognised association), together are characteristic of polyarteritis nodosa, a medium-vessel vasculitis.', 4),
('f2000000-0000-0000-0000-000000000027', 'E', 'Giant cell arteritis', false, 'Ruled out because GCA affects the temporal and other large/medium cranial vessels in older patients, not the mesenteric/renal artery microaneurysm pattern described, and is not associated with hepatitis B.', 5),
('f2000000-0000-0000-0000-000000000028', 'A', 'Giant cell arteritis', false, 'Ruled out because GCA typically affects older patients (over 50) and the cranial/temporal vessels predominantly, not the aortic arch pattern with absent limb pulses seen in a young patient with Takayasu arteritis.', 1),
('f2000000-0000-0000-0000-000000000028', 'B', 'Atherosclerotic peripheral arterial disease', false, 'Ruled out because atherosclerosis affecting multiple large vessels bilaterally in a young woman without vascular risk factors is far less likely than an inflammatory vasculitis; the pattern and age strongly favour Takayasu arteritis.', 2),
('f2000000-0000-0000-0000-000000000028', 'C', 'Takayasu arteritis', true, $x$Correct. Absent peripheral pulses ('pulseless disease'), limb claudication, blood pressure discrepancy between limbs, and thickening/narrowing of the aorta and its major branches on imaging, in a young woman, are characteristic of Takayasu arteritis, a large-vessel granulomatous vasculitis predominantly affecting younger patients.$x$, 3),
('f2000000-0000-0000-0000-000000000028', 'D', 'Fibromuscular dysplasia', false, $x$Ruled out because FMD typically causes a 'string of beads' appearance, most classically in the renal arteries, rather than the diffuse aortic arch thickening and multi-limb pulse loss described here.$x$, 4),
('f2000000-0000-0000-0000-000000000028', 'E', $x$Buerger's disease (thromboangiitis obliterans)$x$, false, $x$Ruled out because Buerger's disease is strongly associated with smoking and affects small and medium distal vessels, not the large aortic arch vessels described here.$x$, 5),
('f2000000-0000-0000-0000-000000000029', 'A', 'Direct toxic effect of the antibiotic on vessel endothelium', false, 'Ruled out because the underlying mechanism of drug-induced leukocytoclastic vasculitis is immune complex-mediated inflammation, not direct toxic endothelial injury.', 1),
('f2000000-0000-0000-0000-000000000029', 'B', 'Immune complex deposition in small vessel walls, triggered by the new medication', true, 'Correct. Cutaneous leukocytoclastic vasculitis is typically caused by immune complex deposition in small dermal vessel walls, triggering complement activation and neutrophilic inflammation; a temporally related new medication is a common recognised trigger, and identification and withdrawal of the causative drug is an important part of management.', 2),
('f2000000-0000-0000-0000-000000000029', 'C', 'Autoimmune destruction of red blood cells', false, 'Ruled out because this describes a haemolytic process, not the vessel wall inflammation (leukocytoclastic vasculitis) described here.', 3),
('f2000000-0000-0000-0000-000000000029', 'D', 'Bacterial invasion of the vessel wall', false, 'Ruled out because leukocytoclastic vasculitis is an immune-mediated, not directly infective, process, even though it can occasionally be triggered by an infection rather than a drug.', 4),
('f2000000-0000-0000-0000-000000000029', 'E', 'Genetic collagen defect affecting vessel structure', false, 'Ruled out because this describes conditions such as Ehlers-Danlos syndrome, not the acquired, immune-mediated inflammatory process of leukocytoclastic vasculitis.', 5),
('f2000000-0000-0000-0000-000000000030', 'A', 'Microscopic polyangiitis', true, 'Correct. Pulmonary involvement (haemoptysis), rapidly progressive (pauci-immune, crescentic) glomerulonephritis, and p-ANCA (anti-MPO) positivity, without the granulomatous upper respiratory tract involvement seen in GPA, is characteristic of microscopic polyangiitis, a small-vessel ANCA-associated vasculitis.', 1),
('f2000000-0000-0000-0000-000000000030', 'B', 'Granulomatosis with polyangiitis', false, 'Ruled out because GPA is typically associated with c-ANCA (anti-PR3) and granulomatous upper respiratory tract involvement (nasal crusting, sinusitis), neither of which is described here; the p-ANCA positivity and absence of upper airway disease favour microscopic polyangiitis.', 2),
('f2000000-0000-0000-0000-000000000030', 'C', 'Goodpasture syndrome (anti-GBM disease)', false, 'Ruled out because anti-GBM disease shows linear immunoglobulin deposition along the glomerular basement membrane on immunofluorescence (not a pauci-immune pattern), and is caused by anti-GBM antibodies, not ANCA.', 3),
('f2000000-0000-0000-0000-000000000030', 'D', 'Lupus nephritis', false, $x$Ruled out because lupus nephritis typically shows significant immune complex deposition on immunofluorescence ('full house' staining), unlike the pauci-immune pattern described here, and would be associated with ANA/anti-dsDNA rather than p-ANCA.$x$, 4),
('f2000000-0000-0000-0000-000000000030', 'E', 'IgA nephropathy', false, 'Ruled out because IgA nephropathy shows mesangial IgA deposition on immunofluorescence, not a pauci-immune pattern, and is not associated with ANCA positivity or this systemic pulmonary-renal presentation.', 5),
('f2000000-0000-0000-0000-000000000031', 'A', 'Gout', true, 'Correct. Acute monoarthritis of the first metatarsophalangeal joint (podagra) with needle-shaped, negatively birefringent crystals (monosodium urate) on joint aspiration is diagnostic of gout, precipitated by risk factors including obesity and alcohol excess.', 1),
('f2000000-0000-0000-0000-000000000031', 'B', 'Pseudogout', false, 'Ruled out because pseudogout is caused by calcium pyrophosphate crystals, which are rhomboid-shaped and positively birefringent, the opposite pattern to the needle-shaped, negatively birefringent crystals described here.', 2),
('f2000000-0000-0000-0000-000000000031', 'C', 'Septic arthritis', false, 'Ruled out because although septic arthritis is an important differential for acute monoarthritis, the specific crystal finding on aspiration confirms gout as the cause in this case.', 3),
('f2000000-0000-0000-0000-000000000031', 'D', 'Rheumatoid arthritis', false, 'Ruled out because RA causes a chronic symmetrical polyarthritis, not this acute monoarthritis with characteristic urate crystals on aspiration.', 4),
('f2000000-0000-0000-0000-000000000031', 'E', 'Reactive arthritis', false, 'Ruled out because reactive arthritis follows a specific infective trigger and would not show urate crystals on joint aspiration.', 5),
('f2000000-0000-0000-0000-000000000032', 'A', 'High-dose NSAID (e.g. naproxen)', false, 'Ruled out because NSAIDs are relatively contraindicated in this patient given both significant renal impairment (risk of further renal injury) and a history of peptic ulcer disease (risk of GI bleeding).', 1),
('f2000000-0000-0000-0000-000000000032', 'B', 'Allopurinol started immediately during the acute attack', false, 'Ruled out because starting urate-lowering therapy during an acute gout flare can worsen or prolong the attack by causing further crystal mobilisation; it is typically started once the acute attack has settled.', 2),
('f2000000-0000-0000-0000-000000000032', 'C', 'Aspirin at anti-inflammatory doses', false, 'Ruled out because high-dose aspirin can actually interfere with urate excretion and is not standard treatment for acute gout, and would carry similar GI risk concerns in this patient.', 3),
('f2000000-0000-0000-0000-000000000032', 'D', 'No treatment, as gout is self-limiting and requires no intervention', false, 'Ruled out because although acute gout attacks can self-resolve over days to weeks, active treatment significantly reduces pain and duration of the attack and is standard practice.', 4),
('f2000000-0000-0000-0000-000000000032', 'E', 'Colchicine, with dose adjustment for renal function', true, 'Correct. In a patient with contraindications to NSAIDs (peptic ulcer disease, significant renal impairment increasing NSAID nephrotoxicity risk), colchicine (with an appropriately reduced dose given renal impairment) is a suitable alternative for treating an acute gout flare, or a short course of corticosteroids could also be considered.', 5),
('f2000000-0000-0000-0000-000000000033', 'A', 'Long-term daily NSAID use as maintenance therapy', false, 'Ruled out because chronic daily NSAID use carries significant long-term gastrointestinal, renal and cardiovascular risk and does not address the underlying hyperuricaemia driving recurrent flares; it is not appropriate long-term maintenance therapy.', 1),
('f2000000-0000-0000-0000-000000000033', 'B', 'No specific long-term treatment, treating each flare individually as it occurs', false, 'Ruled out because recurrent flares with persistently elevated urate is a clear indication for urate-lowering therapy to reduce future attacks and prevent long-term joint damage (chronic tophaceous gout), not just symptomatic treatment of each episode.', 2),
('f2000000-0000-0000-0000-000000000033', 'C', 'Start allopurinol (urate-lowering therapy), once any acute flare has settled', true, 'Correct. Recurrent gout flares with persistently elevated serum urate is an indication for long-term urate-lowering therapy, typically allopurinol, started once any acute attack has resolved and usually with concurrent short-term prophylaxis (e.g. colchicine) to reduce the risk of a flare triggered by the initiation of treatment.', 3),
('f2000000-0000-0000-0000-000000000033', 'D', 'Long-term high-dose colchicine as monotherapy for urate control', false, 'Ruled out because colchicine reduces inflammation during attacks and can be used short-term for prophylaxis when starting urate-lowering therapy, but does not itself lower serum urate; it is not a substitute for a urate-lowering agent.', 4),
('f2000000-0000-0000-0000-000000000033', 'E', 'Dietary modification alone, without any medication', false, 'Ruled out because although dietary modification (reducing purine intake, alcohol, sugary drinks) is a helpful adjunct, it is often insufficient alone to adequately control urate levels in patients with recurrent flares, and pharmacological urate-lowering therapy is indicated.', 5),
('f2000000-0000-0000-0000-000000000034', 'A', 'Gout', false, 'Ruled out because gout is caused by needle-shaped, negatively birefringent monosodium urate crystals, the opposite crystal morphology and birefringence to that described here.', 1),
('f2000000-0000-0000-0000-000000000034', 'B', 'Septic arthritis', false, 'Ruled out because although septic arthritis is an important differential for acute monoarthritis, the specific crystal finding confirms pseudogout as the cause here.', 2),
('f2000000-0000-0000-0000-000000000034', 'C', 'Osteoarthritis flare', false, 'Ruled out because osteoarthritis does not typically present with this degree of acute inflammation and would not show positively birefringent crystals on aspiration.', 3),
('f2000000-0000-0000-0000-000000000034', 'D', 'Pseudogout (calcium pyrophosphate deposition disease)', true, 'Correct. Acute monoarthritis with rhomboid-shaped, positively birefringent crystals (calcium pyrophosphate) on joint aspiration, along with chondrocalcinosis on X-ray (cartilage calcification), confirms pseudogout, which typically affects larger joints such as the knee in older patients.', 4),
('f2000000-0000-0000-0000-000000000034', 'E', 'Rheumatoid arthritis', false, 'Ruled out because RA causes a chronic symmetrical polyarthritis without crystal findings on joint aspiration, unlike the acute crystal-confirmed monoarthritis described here.', 5),
('f2000000-0000-0000-0000-000000000035', 'A', 'Hypoparathyroidism', false, 'Ruled out because hypoparathyroidism causes hypocalcaemia with low (not raised) PTH, the opposite biochemical pattern to that described, though hypoparathyroidism is itself also separately associated with CPPD in some cases.', 1),
('f2000000-0000-0000-0000-000000000035', 'B', 'Primary hyperparathyroidism', true, 'Correct. Calcium pyrophosphate deposition disease (pseudogout) is associated with several metabolic conditions, including primary hyperparathyroidism, haemochromatosis, hypomagnesaemia and hypothyroidism; the combination of hypercalcaemia with raised PTH here specifically points to hyperparathyroidism as the underlying association warranting further workup.', 2),
('f2000000-0000-0000-0000-000000000035', 'C', $x$Addison's disease$x$, false, $x$Ruled out because Addison's disease causes hyponatraemia and hyperkalaemia, not the hypercalcaemia with raised PTH described here, and is not a recognised association with pseudogout.$x$, 3),
('f2000000-0000-0000-0000-000000000035', 'D', $x$Cushing's syndrome$x$, false, $x$Ruled out because Cushing's syndrome does not typically cause hypercalcaemia with raised PTH, and is not a recognised metabolic association with pseudogout.$x$, 4),
('f2000000-0000-0000-0000-000000000035', 'E', 'Type 1 diabetes', false, 'Ruled out because type 1 diabetes is not a recognised metabolic association with pseudogout, and does not explain the hypercalcaemia with raised PTH described here.', 5),
('f2000000-0000-0000-0000-000000000036', 'A', 'Rheumatoid nodules', false, $x$Ruled out because rheumatoid nodules occur in the context of rheumatoid arthritis (typically seropositive, erosive disease), not longstanding gout, and this patient's history and nodule distribution (including the ear helix) is classic for tophi instead.$x$, 1),
('f2000000-0000-0000-0000-000000000036', 'B', 'Xanthomata', false, 'Ruled out because xanthomata reflect lipid deposition associated with hyperlipidaemia, not urate deposition, and would not typically occur specifically in the context of longstanding poorly controlled gout in this pattern.', 2),
('f2000000-0000-0000-0000-000000000036', 'C', 'Gouty tophi', true, 'Correct. Firm, chalky white nodules over extensor surfaces (elbows) and the ear helix in a patient with longstanding poorly controlled gout are tophi, representing deposits of monosodium urate crystals accumulated over time in soft tissue, reflecting chronic tophaceous gout.', 3),
('f2000000-0000-0000-0000-000000000036', 'D', $x$Heberden's nodes$x$, false, $x$Ruled out because Heberden's nodes are bony osteoarthritic swellings at the distal interphalangeal joints, not soft tissue nodules at the elbow and ear helix.$x$, 4),
('f2000000-0000-0000-0000-000000000036', 'E', 'Rheumatic fever nodules', false, 'Ruled out because rheumatic fever subcutaneous nodules occur in the context of acute rheumatic fever, an entirely different condition unrelated to chronic gout.', 5),
('f2000000-0000-0000-0000-000000000037', 'A', 'A simple, mild drug allergy requiring no specific action', false, 'Ruled out because the severity described (widespread blistering, mucosal involvement, significant skin detachment) indicates a life-threatening severe cutaneous adverse reaction, not a mild allergy that can be disregarded.', 1),
('f2000000-0000-0000-0000-000000000037', 'B', 'Chronic tophaceous gout flare', false, 'Ruled out because a gout flare would cause joint symptoms, not a widespread blistering skin reaction with mucosal involvement, which is specific to a severe drug hypersensitivity reaction.', 2),
('f2000000-0000-0000-0000-000000000037', 'C', 'Psoriasis flare', false, 'Ruled out because psoriasis causes scaly plaques, not the acute blistering, mucosal involvement and skin detachment described, which is characteristic of SJS/TEN.', 3),
('f2000000-0000-0000-0000-000000000037', 'D', 'Stevens-Johnson syndrome/toxic epidermal necrolysis secondary to allopurinol', true, 'Correct. Allopurinol is a well-recognised cause of severe cutaneous adverse reactions, including Stevens-Johnson syndrome and toxic epidermal necrolysis, particularly in the first weeks of treatment; this presentation (widespread blistering, mucosal involvement, skin detachment) requires immediate drug discontinuation and urgent specialist (burns/dermatology) management given the high associated mortality.', 4),
('f2000000-0000-0000-0000-000000000037', 'E', 'Normal expected side effect of allopurinol requiring no change in treatment', false, 'Ruled out because SJS/TEN is a rare but serious, potentially fatal reaction requiring immediate drug cessation, not a routine or expected side effect to be tolerated.', 5),
('f2000000-0000-0000-0000-000000000038', 'A', 'Allopurinol inhibits xanthine oxidase, which metabolises azathioprine, risking severe bone marrow suppression if the azathioprine dose is not substantially reduced', true, $x$Correct. Allopurinol inhibits xanthine oxidase, the enzyme responsible for metabolising azathioprine's active metabolite; co-administration without a significant azathioprine dose reduction (typically to around a quarter to a third of the original dose) risks severe, potentially life-threatening bone marrow suppression.$x$, 1),
('f2000000-0000-0000-0000-000000000038', 'B', 'There is no significant interaction between these two drugs', false, 'Ruled out because this is a well-recognised, clinically important drug interaction that must be actively managed, not overlooked as insignificant.', 2),
('f2000000-0000-0000-0000-000000000038', 'C', 'Azathioprine should be increased to compensate for reduced efficacy', false, $x$Ruled out because allopurinol increases (not decreases) azathioprine's active drug levels by inhibiting its metabolism; the azathioprine dose should be reduced, not increased, when co-prescribed with allopurinol.$x$, 3),
('f2000000-0000-0000-0000-000000000038', 'D', 'Allopurinol should be given at a higher dose to overcome the interaction', false, 'Ruled out because increasing the allopurinol dose would further inhibit azathioprine metabolism, worsening the risk of bone marrow suppression rather than addressing it.', 4),
('f2000000-0000-0000-0000-000000000038', 'E', 'The interaction only becomes relevant if renal function is significantly impaired', false, 'Ruled out because although renal impairment further affects drug clearance, this interaction is clinically significant and must be managed regardless of baseline renal function through appropriate azathioprine dose reduction.', 5),
('f2000000-0000-0000-0000-000000000039', 'A', 'Presence of needle-shaped, negatively birefringent crystals', false, 'Ruled out because this finding is diagnostic of gout, not septic arthritis; the two conditions can occasionally coexist, but crystal presence alone does not exclude infection, and this finding itself supports a crystal, not infective, diagnosis.', 1),
('f2000000-0000-0000-0000-000000000039', 'B', 'Presence of rhomboid-shaped, positively birefringent crystals', false, 'Ruled out because this finding is diagnostic of pseudogout, not septic arthritis.', 2),
('f2000000-0000-0000-0000-000000000039', 'C', 'Mildly raised synovial white cell count with no organisms seen', false, 'Ruled out because a mildly raised count without organisms is less suggestive of septic arthritis than markedly raised counts with organisms visualised and cultured.', 3),
('f2000000-0000-0000-0000-000000000039', 'D', 'Clear, straw-coloured synovial fluid with a low white cell count', false, 'Ruled out because this appearance is more typical of a non-inflammatory or mildly inflammatory process, not the purulent, organism-laden fluid expected in septic arthritis.', 4),
('f2000000-0000-0000-0000-000000000039', 'E', 'Gram-positive cocci seen on Gram stain and a markedly elevated synovial fluid white cell count with organism growth on culture', true, 'Correct. Direct visualisation of organisms on Gram stain, a markedly elevated synovial white cell count (often with a high proportion of neutrophils), and confirmed organism growth on culture are the key findings distinguishing septic arthritis from crystal arthropathy, which would instead show crystals without organisms.', 5),
('f2000000-0000-0000-0000-000000000040', 'A', 'Start allopurinol immediately to prevent future gout attacks', false, 'Ruled out because urate-lowering therapy is not routinely started for asymptomatic hyperuricaemia alone; it is reserved for confirmed symptomatic gout or specific high-risk situations.', 1),
('f2000000-0000-0000-0000-000000000040', 'B', 'No treatment is required, as asymptomatic hyperuricaemia alone does not require urate-lowering therapy', true, 'Correct. Asymptomatic hyperuricaemia (a raised serum urate without gout symptoms, tophi, or urate-related complications such as urate nephropathy) does not routinely require urate-lowering therapy, as most people with hyperuricaemia never develop gout, and treatment is reserved for those with confirmed gout or specific risk factors.', 2),
('f2000000-0000-0000-0000-000000000040', 'C', 'Arrange urgent joint aspiration despite no joint symptoms', false, 'Ruled out because joint aspiration is performed to investigate an acutely symptomatic joint, not as a routine investigation for asymptomatic hyperuricaemia with no joint symptoms.', 3),
('f2000000-0000-0000-0000-000000000040', 'D', 'Start colchicine prophylaxis indefinitely', false, 'Ruled out because colchicine prophylaxis is used alongside starting urate-lowering therapy to prevent flares during initiation, not as standalone indefinite treatment for asymptomatic hyperuricaemia.', 4),
('f2000000-0000-0000-0000-000000000040', 'E', 'Recommend a strict zero-purine diet as the sole intervention', false, 'Ruled out because dietary modification may be reasonable general advice, but asymptomatic hyperuricaemia alone does not mandate strict dietary intervention as a primary treatment requirement.', 5),
('f2000000-0000-0000-0000-000000000041', 'A', 'Ankylosing spondylitis', true, $x$Correct. Chronic inflammatory back pain (nocturnal, improving with exercise) in a young man with reduced spinal mobility (positive Schober's test) and reduced chest expansion (from costovertebral joint involvement) is characteristic of ankylosing spondylitis.$x$, 1),
('f2000000-0000-0000-0000-000000000041', 'B', 'Mechanical low back pain', false, 'Ruled out because mechanical back pain worsens with activity and improves with rest, the opposite of the inflammatory pattern described, and would not cause reduced chest expansion.', 2),
('f2000000-0000-0000-0000-000000000041', 'C', 'Fibromyalgia', false, 'Ruled out because fibromyalgia causes diffuse tender points and widespread pain without the objective findings of reduced spinal mobility and reduced chest expansion seen here.', 3),
('f2000000-0000-0000-0000-000000000041', 'D', 'Osteoporotic vertebral fracture', false, 'Ruled out because this would typically present with acute, localised pain following minimal trauma, not a chronic inflammatory pattern with reduced chest expansion in a young man.', 4),
('f2000000-0000-0000-0000-000000000041', 'E', 'Lumbar spinal stenosis', false, 'Ruled out because spinal stenosis classically causes neurogenic claudication (leg pain on walking, relieved by flexion/sitting) in older patients, not this inflammatory back pain pattern in a young man.', 5),
('f2000000-0000-0000-0000-000000000042', 'A', 'Conjunctivitis', false, 'Ruled out because simple conjunctivitis does not cause an irregular pupil or the degree of photophobia and ciliary flush described, which are specific to anterior uveitis.', 1),
('f2000000-0000-0000-0000-000000000042', 'B', 'Acute angle-closure glaucoma', false, 'Ruled out because although this also causes a painful red eye, it typically presents with a fixed, mid-dilated (not irregular, constricted) pupil and a hazy cornea, and is not the classic extra-articular association with ankylosing spondylitis.', 2),
('f2000000-0000-0000-0000-000000000042', 'C', 'Episcleritis', false, 'Ruled out because episcleritis typically causes mild redness and discomfort without significant photophobia or pupil changes, unlike the more severe presentation described here.', 3),
('f2000000-0000-0000-0000-000000000042', 'D', 'Acute anterior uveitis', true, 'Correct. Painful red eye with photophobia, an irregular pupil (from posterior synechiae) and ciliary flush in a patient with ankylosing spondylitis is characteristic of acute anterior uveitis, a common extra-articular manifestation strongly associated with HLA-B27-related spondyloarthropathies, requiring urgent ophthalmology assessment and treatment to prevent complications.', 4),
('f2000000-0000-0000-0000-000000000042', 'E', 'Herpes zoster ophthalmicus', false, 'Ruled out because there is no vesicular rash described, and the specific clinical picture (irregular pupil, ciliary flush) in a patient with known ankylosing spondylitis points to anterior uveitis.', 5),
('f2000000-0000-0000-0000-000000000043', 'A', 'Ankylosing spondylitis unrelated to his psoriasis', false, 'Ruled out because in the context of established psoriasis, the axial disease is better classified as psoriatic arthritis with axial involvement rather than a coincidental, separate diagnosis of ankylosing spondylitis.', 1),
('f2000000-0000-0000-0000-000000000043', 'B', 'Rheumatoid arthritis', false, 'Ruled out because RA does not cause dactylitis or axial spondylitic involvement, and is not linked to psoriasis in this way.', 2),
('f2000000-0000-0000-0000-000000000043', 'C', 'Psoriatic arthritis with axial (spondylitic) involvement', true, 'Correct. Inflammatory back pain and dactylitis in a patient with established psoriasis reflects psoriatic arthritis with axial involvement, one of several patterns psoriatic arthritis can take (alongside asymmetric oligoarthritis, symmetric polyarthritis, distal interphalangeal predominant, and arthritis mutilans).', 3),
('f2000000-0000-0000-0000-000000000043', 'D', 'Osteoarthritis', false, 'Ruled out because osteoarthritis does not cause inflammatory axial symptoms or dactylitis, and does not relate specifically to underlying psoriasis.', 4),
('f2000000-0000-0000-0000-000000000043', 'E', 'Fibromyalgia', false, 'Ruled out because fibromyalgia does not cause objective dactylitis or a specific pattern of axial inflammatory disease linked to psoriasis.', 5),
('f2000000-0000-0000-0000-000000000044', 'A', 'Achilles tendon rupture', false, 'Ruled out because tendon rupture would cause acute inability to plantarflex the foot with a palpable defect, not the inflammatory heel pain (enthesitis) described in the context of a broader spondyloarthropathy picture.', 1),
('f2000000-0000-0000-0000-000000000044', 'B', 'Osteomyelitis of the calcaneus', false, 'Ruled out because there is no mention of fever, systemic infection or imaging findings of bone infection; the clinical context (post-infective oligoarthritis with heel pain) points to enthesitis as part of a spondyloarthropathy, not bone infection.', 2),
('f2000000-0000-0000-0000-000000000044', 'C', 'Plantar fasciitis unrelated to the arthritis', false, 'Ruled out because although plantar fasciitis is also a recognised enthesitis site in spondyloarthropathy, the specific site described (Achilles tendon insertion) is a classic enthesitis location, best explained as part of the same underlying inflammatory process rather than an unrelated separate condition.', 3),
('f2000000-0000-0000-0000-000000000044', 'D', 'Gout affecting the heel', false, 'Ruled out because there is no crystal confirmation, and the overall clinical picture (post-infective oligoarthritis with entheseal pain) is classic for reactive arthritis rather than gout.', 4),
('f2000000-0000-0000-0000-000000000044', 'E', 'Enthesitis (inflammation at the tendon insertion site)', true, 'Correct. Inflammation at entheses (the sites where tendons and ligaments attach to bone), such as the Achilles tendon insertion, is a hallmark feature of the seronegative spondyloarthropathies, including reactive arthritis triggered by a preceding gastrointestinal infection.', 5),
('f2000000-0000-0000-0000-000000000045', 'A', $x$Rheumatoid arthritis coincidentally occurring alongside Crohn's disease$x$, false, 'Ruled out because the specific combination of axial and peripheral inflammatory joint symptoms in a patient with IBD is best classified as enteropathic arthritis, a recognised, specific association, rather than a coincidental separate diagnosis of rheumatoid arthritis.', 1),
('f2000000-0000-0000-0000-000000000045', 'B', 'Enteropathic arthritis (associated with inflammatory bowel disease)', true, $x$Correct. Inflammatory back pain and peripheral arthritis occurring in a patient with established inflammatory bowel disease (Crohn's disease) is characteristic of enteropathic arthritis, one of the seronegative spondyloarthropathies, which can occur independently of bowel disease activity.$x$, 2),
('f2000000-0000-0000-0000-000000000045', 'C', 'Osteoarthritis', false, 'Ruled out because osteoarthritis does not cause inflammatory-pattern back pain or link specifically to underlying IBD.', 3),
('f2000000-0000-0000-0000-000000000045', 'D', 'Fibromyalgia secondary to chronic IBD', false, 'Ruled out because fibromyalgia causes diffuse pain without objective joint swelling, unlike the described knee swelling and inflammatory back pain, which point to a specific spondyloarthropathy.', 4),
('f2000000-0000-0000-0000-000000000045', 'E', 'Septic arthritis of the knee', false, 'Ruled out because there is no fever or systemic infective picture described, and the combination with inflammatory back pain in the context of known IBD points to enteropathic arthritis rather than infection.', 5),
('f2000000-0000-0000-0000-000000000046', 'A', 'HLA-DR4', false, 'Ruled out because HLA-DR4 is associated with rheumatoid arthritis, not the seronegative spondyloarthropathies.', 1),
('f2000000-0000-0000-0000-000000000046', 'B', 'HLA-DR3', false, 'Ruled out because HLA-DR3 is associated with conditions such as type 1 diabetes and certain autoimmune endocrine disorders, not specifically the seronegative spondyloarthropathies.', 2),
('f2000000-0000-0000-0000-000000000046', 'C', 'HLA-B8', false, 'Ruled out because HLA-B8 is associated with various autoimmune conditions (e.g. some autoimmune endocrine and liver diseases) but is not the characteristic allele linked to spondyloarthropathy.', 3),
('f2000000-0000-0000-0000-000000000046', 'D', 'HLA-B27', true, 'Correct. HLA-B27 is strongly associated with the seronegative spondyloarthropathies (ankylosing spondylitis, psoriatic arthritis, reactive arthritis, enteropathic arthritis), particularly with axial disease, though it is neither fully sensitive nor specific, and the majority of HLA-B27-positive individuals never develop disease.', 4),
('f2000000-0000-0000-0000-000000000046', 'E', 'HLA-DQ2', false, 'Ruled out because HLA-DQ2 is associated with coeliac disease, not the seronegative spondyloarthropathies.', 5),
('f2000000-0000-0000-0000-000000000047', 'A', 'Osteophytosis', false, 'Ruled out because osteophytes are a feature of degenerative osteoarthritis, typically producing more irregular, non-bridging bony spurs, not the specific continuous bridging fusion pattern described here.', 1),
('f2000000-0000-0000-0000-000000000047', 'B', 'Bamboo spine', true, 'Correct. Bridging syndesmophytes (bony growths connecting adjacent vertebral bodies) fusing across multiple levels, giving a continuous, segmented appearance resembling bamboo, is the classic late radiographic finding in advanced ankylosing spondylitis.', 2),
('f2000000-0000-0000-0000-000000000047', 'C', 'Spondylolisthesis', false, 'Ruled out because spondylolisthesis refers to anterior slippage of one vertebral body relative to another, not the bridging fusion appearance described.', 3),
('f2000000-0000-0000-0000-000000000047', 'D', 'Vertebral compression fracture', false, 'Ruled out because compression fracture describes vertebral body height loss from collapse, not the bridging syndesmophyte fusion pattern described.', 4),
('f2000000-0000-0000-0000-000000000047', 'E', $x$Scheuermann's disease$x$, false, $x$Ruled out because Scheuermann's disease is a condition of adolescent vertebral wedging and kyphosis, unrelated to the syndesmophyte bridging seen in advanced ankylosing spondylitis.$x$, 5),
('f2000000-0000-0000-0000-000000000048', 'A', 'Regular physiotherapy and exercise, particularly focused on spinal extension and posture, are a core part of long-term management', true, 'Correct. Regular exercise and physiotherapy, emphasising spinal extension exercises, posture and mobility, form a core component of ankylosing spondylitis management alongside pharmacological treatment, helping maintain spinal mobility, reduce stiffness and slow the progression of postural deformity.', 1),
('f2000000-0000-0000-0000-000000000048', 'B', 'Complete rest and avoidance of physical activity is recommended to reduce joint stress', false, 'Ruled out because prolonged inactivity in ankylosing spondylitis worsens stiffness and accelerates loss of spinal mobility; regular, appropriate exercise is specifically encouraged, not avoided.', 2),
('f2000000-0000-0000-0000-000000000048', 'C', 'Exercise has no meaningful role and management should focus solely on medication', false, 'Ruled out because exercise and physiotherapy are evidence-based, core components of management, working alongside (not replaced by) pharmacological treatment.', 3),
('f2000000-0000-0000-0000-000000000048', 'D', 'High-impact contact sports should be actively encouraged without restriction', false, 'Ruled out because although general exercise is encouraged, activities carrying a high risk of spinal trauma should be approached with caution, particularly in patients with more advanced spinal fusion, given the increased fracture risk of a rigid spine.', 4),
('f2000000-0000-0000-0000-000000000048', 'E', 'Swimming and other low-impact activities should be specifically avoided', false, 'Ruled out because low-impact activities such as swimming are generally well-suited and often specifically recommended for patients with ankylosing spondylitis, supporting mobility without excessive joint stress.', 5),
('f2000000-0000-0000-0000-000000000049', 'A', 'A conventional synthetic DMARD such as methotrexate for axial symptoms', false, 'Ruled out because conventional synthetic DMARDs have not demonstrated significant efficacy for the axial (spinal) manifestations of ankylosing spondylitis, in contrast to their role in peripheral joint disease; biologic therapy is preferred for axial symptoms not controlled by NSAIDs.', 1),
('f2000000-0000-0000-0000-000000000049', 'B', 'Long-term high-dose oral corticosteroids', false, 'Ruled out because long-term oral corticosteroids are not standard treatment for ankylosing spondylitis and carry significant cumulative toxicity; they are not the recommended escalation step here.', 2),
('f2000000-0000-0000-0000-000000000049', 'C', 'Spinal fusion surgery', false, 'Ruled out because surgery is reserved for specific structural complications (e.g. severe deformity, fracture), not as the standard next step for ongoing pain/stiffness after NSAID failure.', 3),
('f2000000-0000-0000-0000-000000000049', 'D', 'No further treatment, as NSAID failure indicates no further options are available', false, 'Ruled out because biologic therapy offers an effective further treatment option for patients who do not respond adequately to NSAIDs, and should be considered rather than concluding no options remain.', 4),
('f2000000-0000-0000-0000-000000000049', 'E', 'A biologic DMARD, such as a TNF-alpha inhibitor', true, 'Correct. In ankylosing spondylitis with ongoing significant symptoms despite an adequate trial of NSAIDs and physiotherapy, escalation to a biologic agent (typically a TNF-alpha inhibitor) is the recommended next step, as conventional synthetic DMARDs (e.g. methotrexate, sulfasalazine) have limited efficacy for axial disease specifically.', 5),
('f2000000-0000-0000-0000-000000000050', 'A', 'Simple soft tissue back strain', false, 'Ruled out because the combination of significant trauma in a patient with a known rigid, fused spine, together with new bilateral leg weakness, indicates a much more serious injury than simple soft tissue strain, requiring urgent exclusion of fracture and cord compromise.', 1),
('f2000000-0000-0000-0000-000000000050', 'B', 'Reactivation of his underlying inflammatory spinal disease', false, 'Ruled out because the acute onset following a fall, with new neurological deficit, points to a traumatic fracture, not a gradual inflammatory flare of his underlying condition.', 2),
('f2000000-0000-0000-0000-000000000050', 'C', 'Vertebral fracture with spinal cord compromise', true, 'Correct. A rigid, fused spine in advanced ankylosing spondylitis is highly susceptible to fracture even from relatively minor trauma, and such fractures carry a significant risk of spinal cord injury; new bilateral leg weakness after even a low-energy fall in this context is a neurosurgical emergency requiring urgent imaging and specialist assessment.', 3),
('f2000000-0000-0000-0000-000000000050', 'D', 'Simple muscular spasm', false, 'Ruled out because muscular spasm alone would not explain new bilateral leg weakness, which indicates a significant neurological insult requiring urgent investigation.', 4),
('f2000000-0000-0000-0000-000000000050', 'E', 'Referred pain from an unrelated abdominal cause', false, 'Ruled out because the clear traumatic mechanism (a fall) in a patient with a rigid spine, combined with new bilateral leg weakness, points specifically to a spinal injury, not a referred abdominal cause.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f2000000-0000-0000-0000-000000000001', 'Anti-CCP antibodies are highly specific for rheumatoid arthritis and, when positive alongside rheumatoid factor, strongly support this diagnosis over other inflammatory arthropathies.', 1),
('f2000000-0000-0000-0000-000000000001', 'Symmetrical involvement of the MCP and PIP joints, sparing the DIP joints, is a classic distributional pattern for rheumatoid arthritis, distinguishing it from osteoarthritis (which favours DIP and first CMC joints).', 2),
('f2000000-0000-0000-0000-000000000001', 'Morning stiffness lasting more than an hour reflects an inflammatory (rather than degenerative) arthropathy, supporting rheumatoid arthritis over osteoarthritis.', 3),
('f2000000-0000-0000-0000-000000000002', $x$Methotrexate's specific side-effect profile (hepatotoxicity, bone marrow suppression, and the less common but important pneumonitis) necessitates regular blood test monitoring throughout treatment.$x$, 1),
('f2000000-0000-0000-0000-000000000002', 'Folic acid supplementation, given on a different day to the weekly methotrexate dose, helps reduce certain side effects (e.g. mucositis, some cytopenias) without compromising efficacy.', 2),
('f2000000-0000-0000-0000-000000000002', $x$As the anchor first-line DMARD for rheumatoid arthritis, methotrexate's monitoring requirements are a frequently tested practical prescribing point.$x$, 3),
('f2000000-0000-0000-0000-000000000003', 'Chronic synovitis in rheumatoid arthritis can erode the transverse ligament and other stabilising structures of the atlantoaxial joint, a recognised and potentially serious extra-articular complication.', 1),
('f2000000-0000-0000-0000-000000000003', 'Neck flexion or manipulation (such as during intubation) can precipitate spinal cord compression in patients with significant atlantoaxial instability, making pre-operative cervical spine assessment important in longstanding RA.', 2),
('f2000000-0000-0000-0000-000000000003', 'Awareness of this complication is clinically important, as it can be prevented by careful anaesthetic and surgical positioning once identified on screening imaging.', 3),
('f2000000-0000-0000-0000-000000000004', $x$Dactylitis (whole-digit, 'sausage' swelling) is a distinctive clinical sign of psoriatic arthritis, reflecting inflammation involving joints, tendon sheaths and entheses together.$x$, 1),
('f2000000-0000-0000-0000-000000000004', 'Nail changes (pitting, onycholysis) frequently accompany psoriatic arthritis and provide an important diagnostic clue, particularly when skin psoriasis itself may be subtle or not volunteered by the patient.', 2),
('f2000000-0000-0000-0000-000000000004', 'A known history of psoriasis is a key contextual clue, though psoriatic arthritis can occasionally precede the skin manifestation.', 3),
('f2000000-0000-0000-0000-000000000005', 'The classic triad of conjunctivitis, urethritis and arthritis (historically termed Reiter syndrome) occurring after a genitourinary or gastrointestinal infection defines reactive arthritis.', 1),
('f2000000-0000-0000-0000-000000000005', 'Reactive arthritis is a sterile, immune-mediated inflammatory response, distinct from a true septic arthritis in which the infecting organism is present within the joint itself.', 2),
('f2000000-0000-0000-0000-000000000005', 'Asymmetrical, lower-limb-predominant oligoarthritis is a typical joint pattern in reactive arthritis, differing from the symmetrical small joint pattern of rheumatoid arthritis.', 3),
('f2000000-0000-0000-0000-000000000006', 'Rheumatoid arthritis is a recognised cause of interstitial lung disease as an extra-articular manifestation, independent of any drug therapy.', 1),
('f2000000-0000-0000-0000-000000000006', 'A basal-predominant reticular pattern with honeycombing on HRCT reflects a usual interstitial pneumonia pattern, one of several patterns seen in rheumatoid-associated ILD.', 2),
('f2000000-0000-0000-0000-000000000006', 'Distinguishing disease-related ILD from drug-induced pneumonitis (e.g. from methotrexate) is clinically important, as it affects decisions about continuing or stopping the causative DMARD.', 3),
('f2000000-0000-0000-0000-000000000007', 'Inflammatory back pain -- morning stiffness lasting over 30 minutes, improvement with exercise, and worsening with rest -- is a key distinguishing feature from mechanical back pain.', 1),
('f2000000-0000-0000-0000-000000000007', $x$Sacroiliitis on imaging is a hallmark early radiographic finding in ankylosing spondylitis, often preceding more advanced spinal changes (e.g. syndesmophytes, 'bamboo spine').$x$, 2),
('f2000000-0000-0000-0000-000000000007', 'HLA-B27 positivity is strongly associated with ankylosing spondylitis, though it is neither fully sensitive nor specific and is interpreted alongside the clinical and radiographic picture.', 3),
('f2000000-0000-0000-0000-000000000008', 'A validated composite disease activity score (such as DAS28) above a defined threshold, despite adequate conventional synthetic DMARD therapy, is the standard trigger for considering biologic therapy.', 1),
('f2000000-0000-0000-0000-000000000008', 'TNF-alpha inhibitors (e.g. adalimumab, etanercept) are typically the first-line biologic class used after conventional DMARD failure, targeting a key inflammatory cytokine in rheumatoid arthritis pathogenesis.', 2),
('f2000000-0000-0000-0000-000000000008', 'Biologic therapy requires specific pre-treatment screening (e.g. for tuberculosis and hepatitis B) given the increased infection risk associated with this class of medication.', 3),
('f2000000-0000-0000-0000-000000000009', 'Longstanding chronic inflammatory conditions (rheumatoid arthritis, inflammatory bowel disease, chronic infections) are the classic drivers of AA amyloidosis, through persistently elevated serum amyloid A.', 1),
('f2000000-0000-0000-0000-000000000009', 'Congo red staining with apple-green birefringence under polarised light is the definitive histological method for confirming amyloid deposition, regardless of the underlying amyloid protein type.', 2),
('f2000000-0000-0000-0000-000000000009', 'Distinguishing AA amyloidosis (secondary to chronic inflammation) from AL amyloidosis (from a plasma cell dyscrasia) is important, as the underlying cause and management differ substantially.', 3),
('f2000000-0000-0000-0000-000000000010', $x$Sjogren syndrome is termed 'secondary' when it occurs alongside another defined autoimmune connective tissue disease (such as rheumatoid arthritis here), as opposed to 'primary' Sjogren syndrome occurring in isolation.$x$, 1),
('f2000000-0000-0000-0000-000000000010', $x$Anti-Ro (SSA) and anti-La (SSB) antibodies are characteristic serological markers of Sjogren syndrome, supporting the clinical diagnosis alongside objective testing such as Schirmer's test.$x$, 2),
('f2000000-0000-0000-0000-000000000010', 'Reduced exocrine gland secretion (tears, saliva) reflects lymphocytic infiltration and destruction of the lacrimal and salivary glands, the underlying pathological process in Sjogren syndrome.', 3),
('f2000000-0000-0000-0000-000000000011', 'A malar (butterfly) rash that characteristically spares the nasolabial folds is a classic cutaneous finding in SLE, and photosensitivity is a recognised triggering/exacerbating factor.', 1),
('f2000000-0000-0000-0000-000000000011', 'Anti-dsDNA antibodies are highly specific for SLE and correlate with disease activity, particularly lupus nephritis, making them useful for both diagnosis and monitoring.', 2),
('f2000000-0000-0000-0000-000000000011', 'Low complement (C3/C4) levels reflect consumption by immune complex formation and activation, supporting active SLE disease.', 3),
('f2000000-0000-0000-0000-000000000012', 'Red cell casts on urine microscopy indicate a glomerular source of bleeding, distinguishing nephritic-pattern kidney involvement from lower urinary tract causes.', 1),
('f2000000-0000-0000-0000-000000000012', 'Lupus nephritis is a major cause of morbidity and mortality in SLE, making prompt recognition and renal biopsy (to determine histological class and guide treatment intensity) important.', 2),
('f2000000-0000-0000-0000-000000000012', 'Regular monitoring of renal function, urinalysis, complement levels and anti-dsDNA titres in known SLE patients helps detect renal flares early, before irreversible damage occurs.', 3),
('f2000000-0000-0000-0000-000000000013', 'Skin thickening confined to the fingers, hands, face and distal forearms (rather than the trunk and proximal limbs) defines limited (as opposed to diffuse) cutaneous systemic sclerosis.', 1),
('f2000000-0000-0000-0000-000000000013', $x$The CREST features (Calcinosis, Raynaud's, oEsophageal dysmotility, Sclerodactyly, Telangiectasia) are classically associated with the limited form and anti-centromere antibody positivity.$x$, 2),
('f2000000-0000-0000-0000-000000000013', 'Limited cutaneous systemic sclerosis carries a lower risk of early severe internal organ involvement compared with the diffuse form, though pulmonary arterial hypertension remains an important long-term risk requiring monitoring.', 3),
('f2000000-0000-0000-0000-000000000014', 'Diffuse (rather than limited) cutaneous systemic sclerosis carries the highest risk of scleroderma renal crisis, particularly early in the disease course.', 1),
('f2000000-0000-0000-0000-000000000014', 'The abrupt onset of severe (often malignant-range) hypertension with acute kidney injury is the hallmark presentation, reflecting acute intrarenal vasculopathy.', 2),
('f2000000-0000-0000-0000-000000000014', $x$ACE inhibitors are specifically effective and are used urgently in scleroderma renal crisis, in contrast to their more cautious use in other causes of acute kidney injury, reflecting the crisis's underlying renin-angiotensin-driven pathophysiology.$x$, 3),
('f2000000-0000-0000-0000-000000000015', $x$The heliotrope rash (violaceous eyelid discolouration, often with periorbital oedema) and Gottron's papules (scaly plaques over extensor joint surfaces, particularly the knuckles) are pathognomonic cutaneous features distinguishing dermatomyositis from polymyositis.$x$, 1),
('f2000000-0000-0000-0000-000000000015', 'A markedly elevated creatine kinase reflects active muscle inflammation and damage, correlating with disease activity and used to monitor treatment response.', 2),
('f2000000-0000-0000-0000-000000000015', 'Dermatomyositis in adults carries an increased association with underlying malignancy, prompting age-appropriate cancer screening at diagnosis.', 3),
('f2000000-0000-0000-0000-000000000016', 'The malignancy association is strongest around the time of dermatomyositis diagnosis, particularly within the first one to two years, justifying screening at this stage.', 1),
('f2000000-0000-0000-0000-000000000016', 'Certain cancers (ovarian, lung, pancreatic, gastric, colorectal, and lymphoma) are more strongly associated, informing which screening tests are prioritised alongside standard age-appropriate screening.', 2),
('f2000000-0000-0000-0000-000000000016', 'This paraneoplastic-type association is much less pronounced in polymyositis and in juvenile dermatomyositis, which is an important distinction when counselling different patient groups.', 3),
('f2000000-0000-0000-0000-000000000017', 'The combination of vascular thrombosis and/or pregnancy morbidity (recurrent miscarriage, particularly in the second/third trimester) with positive antiphospholipid antibodies defines antiphospholipid syndrome.', 1),
('f2000000-0000-0000-0000-000000000017', 'Persistent positivity on repeat testing at least 12 weeks apart is required to confirm the diagnosis, distinguishing true antiphospholipid syndrome from transient antibody positivity (e.g. related to acute infection).', 2),
('f2000000-0000-0000-0000-000000000017', 'Antiphospholipid syndrome can occur alone (primary) or secondary to another autoimmune condition such as SLE, which should be actively considered and screened for at diagnosis.', 3),
('f2000000-0000-0000-0000-000000000018', 'Mixed connective tissue disease is defined by overlapping clinical features of SLE, systemic sclerosis and polymyositis/dermatomyositis occurring together in one patient.', 1),
('f2000000-0000-0000-0000-000000000018', 'A high titre of anti-U1-RNP antibody is the serological hallmark of mixed connective tissue disease, distinguishing it from the individual conditions it overlaps with.', 2),
('f2000000-0000-0000-0000-000000000018', 'Absence of disease-specific antibodies for the individual overlapping conditions (e.g. anti-dsDNA for SLE, anti-Scl-70 for systemic sclerosis) supports MCTD rather than one of these conditions alone.', 3),
('f2000000-0000-0000-0000-000000000019', 'Anti-Ro (and anti-La) antibodies can actively cross the placenta and directly damage fetal cardiac tissue, distinguishing this from many other pregnancy risks that are not antibody-mediated.', 1),
('f2000000-0000-0000-0000-000000000019', 'Congenital heart block typically develops between 18 and 24 weeks of gestation, guiding the timing of serial fetal echocardiographic monitoring in anti-Ro-positive pregnancies.', 2),
('f2000000-0000-0000-0000-000000000019', 'Neonatal lupus syndrome can also cause transient skin rash and cytopenias in the newborn, but congenital heart block is the most serious and often permanent complication requiring active surveillance.', 3),
('f2000000-0000-0000-0000-000000000020', 'UV light-induced keratinocyte apoptosis exposes nuclear antigens at the skin surface, triggering an autoimmune response in genetically predisposed individuals -- the basis for lupus photosensitivity.', 1),
('f2000000-0000-0000-0000-000000000020', 'Patients with SLE are routinely advised on sun protection measures (sunscreen, protective clothing, avoiding peak UV hours) specifically to reduce flare risk.', 2),
('f2000000-0000-0000-0000-000000000020', 'Certain drugs (e.g. some antibiotics, though more classically hydralazine, procainamide and isoniazid) can also trigger lupus-like flares or drug-induced lupus, reinforcing the importance of reviewing new medications during a flare.', 3),
('f2000000-0000-0000-0000-000000000021', 'Jaw claudication is a highly specific symptom for giant cell arteritis, reflecting ischaemia of the muscles of mastication.', 1),
('f2000000-0000-0000-0000-000000000021', 'A markedly raised ESR/CRP in an older patient with new temporal headache strongly supports GCA.', 2),
('f2000000-0000-0000-0000-000000000021', 'Temporal artery biopsy showing granulomatous inflammation with giant cells provides histological confirmation, though treatment should not be delayed for biopsy given the risk of sudden visual loss.', 3),
('f2000000-0000-0000-0000-000000000022', 'Sudden, painless visual loss in a patient with known or suspected GCA should be treated as an emergency, given the high risk of the same process affecting the other eye if not urgently treated.', 1),
('f2000000-0000-0000-0000-000000000022', 'A pale, swollen optic disc on fundoscopy reflects ischaemic damage to the optic nerve head from occluded posterior ciliary arteries, distinguishing this from other causes of acute visual loss.', 2),
('f2000000-0000-0000-0000-000000000022', 'Prompt escalation of corticosteroid treatment (often IV methylprednisolone) is used in an attempt to protect the remaining vision, though visual loss that has already occurred is often irreversible.', 3),
('f2000000-0000-0000-0000-000000000023', 'The classic triad of upper respiratory tract, lower respiratory tract and renal involvement defines granulomatosis with polyangiitis.', 1),
('f2000000-0000-0000-0000-000000000023', 'c-ANCA with anti-PR3 specificity is strongly associated with GPA, distinguishing it serologically from microscopic polyangiitis (typically p-ANCA/anti-MPO).', 2),
('f2000000-0000-0000-0000-000000000023', 'Cavitating pulmonary nodules are a characteristic radiographic finding in GPA, reflecting granulomatous inflammation and necrosis within the lung parenchyma.', 3),
('f2000000-0000-0000-0000-000000000024', 'A preceding history of asthma and allergic rhinitis, followed by a vasculitic phase, is the classic clinical evolution of eosinophilic granulomatosis with polyangiitis.', 1),
('f2000000-0000-0000-0000-000000000024', 'Marked peripheral eosinophilia is a distinguishing laboratory feature of EGPA, differentiating it from other ANCA-associated vasculitides.', 2),
('f2000000-0000-0000-0000-000000000024', 'Peripheral neuropathy (mononeuritis multiplex) is a common and important manifestation of EGPA, reflecting vasculitic involvement of the vasa nervorum.', 3),
('f2000000-0000-0000-0000-000000000025', 'Prolonged fever (5 days or more) combined with the classic mucocutaneous features (conjunctivitis, rash, cracked lips, cervical lymphadenopathy, extremity changes) defines the clinical diagnosis of Kawasaki disease.', 1),
('f2000000-0000-0000-0000-000000000025', 'Coronary artery aneurysm is the most serious complication of Kawasaki disease, making echocardiography an essential part of the initial and follow-up workup.', 2),
('f2000000-0000-0000-0000-000000000025', 'Prompt treatment with IVIG (and aspirin) significantly reduces the risk of coronary artery aneurysm formation, making early recognition and treatment critical.', 3),
('f2000000-0000-0000-0000-000000000026', 'Palpable purpura in dependent, gravity-affected areas (buttocks, lower legs) is characteristic of HSP, reflecting small-vessel leukocytoclastic vasculitis.', 1),
('f2000000-0000-0000-0000-000000000026', 'The classic tetrad of purpura, arthralgia, abdominal pain and renal involvement, often following an upper respiratory infection, defines HSP in children.', 2),
('f2000000-0000-0000-0000-000000000026', 'Renal involvement (haematuria, proteinuria) determines the need for follow-up monitoring, as a minority of children develop longer-term kidney complications requiring nephrology input.', 3),
('f2000000-0000-0000-0000-000000000027', 'Chronic hepatitis B infection is a well-recognised association with polyarteritis nodosa, present in a proportion of cases.', 1),
('f2000000-0000-0000-0000-000000000027', 'Angiographic demonstration of microaneurysms in medium-sized vessels (renal, mesenteric, hepatic) is a classic diagnostic finding in PAN.', 2),
('f2000000-0000-0000-0000-000000000027', 'ANCA negativity distinguishes PAN from the ANCA-associated small-vessel vasculitides (GPA, MPA, EGPA), which is an important part of the diagnostic classification.', 3),
('f2000000-0000-0000-0000-000000000028', 'Young age (typically under 40) and female sex are epidemiologically characteristic of Takayasu arteritis, distinguishing it from giant cell arteritis, which affects an older population.', 1),
('f2000000-0000-0000-0000-000000000028', $x$Absent or diminished pulses and blood pressure discrepancies between limbs reflect large-vessel stenosis, giving rise to the historical term 'pulseless disease.'$x$, 2),
('f2000000-0000-0000-0000-000000000028', 'Imaging showing vessel wall thickening and stenosis of the aorta and its major branches is key to diagnosis, often requiring CT or MR angiography rather than simple Doppler assessment.', 3),
('f2000000-0000-0000-0000-000000000029', 'A clear temporal relationship between starting a new medication and developing a purpuric rash supports a drug-induced trigger for leukocytoclastic vasculitis.', 1),
('f2000000-0000-0000-0000-000000000029', 'Skin biopsy showing leukocytoclastic vasculitis (neutrophilic infiltration with nuclear debris around small vessels) confirms the histological diagnosis, though the trigger (drug, infection, or idiopathic) must be established clinically.', 2),
('f2000000-0000-0000-0000-000000000029', 'Identifying and withdrawing the causative drug is a key management step, often leading to resolution of the vasculitis without further specific immunosuppressive treatment in mild, skin-limited cases.', 3),
('f2000000-0000-0000-0000-000000000030', $x$A 'pauci-immune' pattern (little to no immune complex deposition) on renal immunofluorescence is characteristic of ANCA-associated vasculitis, distinguishing it from immune complex-mediated glomerulonephritis (e.g. lupus nephritis, IgA nephropathy).$x$, 1),
('f2000000-0000-0000-0000-000000000030', 'p-ANCA (anti-MPO) positivity without granulomatous upper respiratory tract disease favours microscopic polyangiitis over granulomatosis with polyangiitis.', 2),
('f2000000-0000-0000-0000-000000000030', $x$Combined pulmonary haemorrhage and rapidly progressive glomerulonephritis defines a 'pulmonary-renal syndrome,' with the immunofluorescence and ANCA pattern helping to distinguish the several possible underlying causes.$x$, 3),
('f2000000-0000-0000-0000-000000000031', 'Needle-shaped, negatively birefringent crystals under polarised light are diagnostic of monosodium urate, confirming gout.', 1),
('f2000000-0000-0000-0000-000000000031', 'The first metatarsophalangeal joint (podagra) is the classic initial site for acute gout, though other joints can also be affected.', 2),
('f2000000-0000-0000-0000-000000000031', 'Risk factors such as obesity, alcohol excess, diuretic use and purine-rich diet contribute to hyperuricaemia, the underlying driver of gout.', 3),
('f2000000-0000-0000-0000-000000000032', 'NSAIDs, though often first-line for acute gout, are relatively or absolutely contraindicated in patients with significant renal impairment or peptic ulcer disease, requiring an alternative such as colchicine or corticosteroids.', 1),
('f2000000-0000-0000-0000-000000000032', 'Colchicine dosing must be adjusted for renal function, as reduced clearance increases the risk of toxicity (particularly gastrointestinal and, at higher doses, bone marrow suppression).', 2),
('f2000000-0000-0000-0000-000000000032', 'Urate-lowering therapy (e.g. allopurinol) is deferred until the acute attack has resolved, as starting it acutely can precipitate further flares through crystal mobilisation, though established therapy is typically continued if already in place.', 3),
('f2000000-0000-0000-0000-000000000033', 'Recurrent gout flares (generally two or more per year) or evidence of tophi/joint damage are indications for starting long-term urate-lowering therapy.', 1),
('f2000000-0000-0000-0000-000000000033', 'Allopurinol is typically started at a low dose once any acute attack has resolved, titrated to achieve a target serum urate level, to reduce the risk of future flares and long-term joint damage.', 2),
('f2000000-0000-0000-0000-000000000033', 'Short-term prophylaxis (e.g. colchicine or an NSAID) is often co-prescribed when starting urate-lowering therapy, as the initial fluctuation in urate levels can itself paradoxically trigger a flare.', 3),
('f2000000-0000-0000-0000-000000000034', 'Rhomboid-shaped, weakly positively birefringent crystals under polarised light are diagnostic of calcium pyrophosphate, confirming pseudogout, in contrast to the needle-shaped, negatively birefringent crystals of gout.', 1),
('f2000000-0000-0000-0000-000000000034', 'Chondrocalcinosis (calcification of articular cartilage) on X-ray is a supportive radiographic finding in calcium pyrophosphate deposition disease.', 2),
('f2000000-0000-0000-0000-000000000034', 'Pseudogout more commonly affects larger joints (knee, wrist) and older patients compared with gout, which classically affects the first MTP joint, though there is overlap.', 3),
('f2000000-0000-0000-0000-000000000035', 'Several metabolic conditions (hyperparathyroidism, haemochromatosis, hypomagnesaemia, hypothyroidism) are recognised associations with calcium pyrophosphate deposition disease, particularly when it presents at a younger age or is recurrent/severe.', 1),
('f2000000-0000-0000-0000-000000000035', 'Hypercalcaemia with an inappropriately raised (rather than suppressed) PTH specifically indicates primary hyperparathyroidism as the cause.', 2),
('f2000000-0000-0000-0000-000000000035', 'Identifying and treating an underlying metabolic association can be relevant to overall management, even though acute pseudogout attacks are treated symptomatically regardless of cause.', 3),
('f2000000-0000-0000-0000-000000000036', 'Tophi develop after years of poorly controlled hyperuricaemia, reflecting chronic urate crystal deposition in soft tissues.', 1),
('f2000000-0000-0000-0000-000000000036', 'Characteristic sites include the helix of the ear, extensor surfaces of the elbows, and around joints, distinguishing tophi from other subcutaneous nodules by both location and clinical context.', 2),
('f2000000-0000-0000-0000-000000000036', 'The presence of tophi indicates a need for more aggressive long-term urate-lowering therapy to reduce further deposition and, over time, gradually reduce their size.', 3),
('f2000000-0000-0000-0000-000000000037', 'The first few weeks to months of allopurinol therapy carry the highest risk period for severe cutaneous adverse reactions, including SJS/TEN.', 1),
('f2000000-0000-0000-0000-000000000037', 'Mucosal involvement and significant skin detachment distinguish severe reactions (SJS/TEN) from milder maculopapular drug rashes, and mandate immediate drug withdrawal and urgent specialist care.', 2),
('f2000000-0000-0000-0000-000000000037', 'Certain genetic factors (e.g. HLA-B*5801, particularly prevalent in some Asian populations) are associated with increased risk of allopurinol-induced severe cutaneous adverse reactions, informing pre-treatment screening in some settings.', 3),
('f2000000-0000-0000-0000-000000000038', $x$Allopurinol's inhibition of xanthine oxidase is the specific pharmacological mechanism underlying this well-recognised, potentially dangerous interaction with azathioprine (and 6-mercaptopurine).$x$, 1),
('f2000000-0000-0000-0000-000000000038', 'A substantial reduction in azathioprine dose (commonly to a quarter to a third of the original dose) is required when allopurinol is co-prescribed, alongside close monitoring of full blood count.', 2),
('f2000000-0000-0000-0000-000000000038', 'Awareness of this interaction is important whenever a patient on azathioprine or 6-mercaptopurine requires treatment for gout, prompting consideration of alternative urate-lowering agents if dose adjustment and monitoring cannot be reliably achieved.', 3),
('f2000000-0000-0000-0000-000000000039', 'Direct organism visualisation on Gram stain and positive culture provide definitive microbiological confirmation of septic arthritis, distinguishing it from crystal arthropathies.', 1),
('f2000000-0000-0000-0000-000000000039', 'A markedly elevated synovial white cell count, particularly with a high neutrophil predominance, is strongly suggestive of infection, though very high counts can occasionally also be seen in severe crystal arthritis.', 2),
('f2000000-0000-0000-0000-000000000039', 'Septic arthritis is a surgical and medical emergency requiring urgent joint washout and antibiotics, particularly critical to identify promptly in the context of a recent prosthetic joint, where infection can jeopardise the implant.', 3),
('f2000000-0000-0000-0000-000000000040', 'The majority of people with hyperuricaemia never develop clinical gout, meaning the biochemical finding alone is not an indication for treatment.', 1),
('f2000000-0000-0000-0000-000000000040', 'Urate-lowering therapy is reserved for confirmed gout (recurrent flares, tophi, joint damage) or specific situations such as tumour lysis syndrome prevention, not simply an elevated blood level found incidentally.', 2),
('f2000000-0000-0000-0000-000000000040', 'This distinction is an important, frequently tested point, as it prevents unnecessary medicalisation and treatment of a common incidental biochemical finding.', 3),
('f2000000-0000-0000-0000-000000000041', $x$Schober's test (measuring lumbar spine flexion) provides an objective assessment of reduced spinal mobility, a key examination finding in ankylosing spondylitis.$x$, 1),
('f2000000-0000-0000-0000-000000000041', 'Reduced chest expansion reflects costovertebral joint involvement, an extra-spinal manifestation helping support the diagnosis.', 2),
('f2000000-0000-0000-0000-000000000041', 'The inflammatory pattern of pain (worse at night/early morning, improving with exercise) is a key discriminator from the mechanical back pain pattern seen in most other causes of back pain.', 3),
('f2000000-0000-0000-0000-000000000042', 'Acute anterior uveitis is a well-recognised extra-articular manifestation occurring in a significant proportion of patients with ankylosing spondylitis and other HLA-B27-associated spondyloarthropathies.', 1),
('f2000000-0000-0000-0000-000000000042', 'An irregular pupil from posterior synechiae (adhesions between the iris and lens) and ciliary flush are classic examination findings distinguishing uveitis from simpler causes of red eye.', 2),
('f2000000-0000-0000-0000-000000000042', 'Prompt ophthalmology referral and treatment (typically topical corticosteroids and mydriatics) are important to prevent complications such as glaucoma or cataract from recurrent or untreated episodes.', 3),
('f2000000-0000-0000-0000-000000000043', 'Psoriatic arthritis can present with several distinct patterns, including an axial (spondylitic) form that clinically resembles ankylosing spondylitis but occurs in the context of psoriasis.', 1),
('f2000000-0000-0000-0000-000000000043', 'Dactylitis, when present alongside axial symptoms, supports a psoriatic (rather than purely idiopathic ankylosing spondylitis) process.', 2),
('f2000000-0000-0000-0000-000000000043', 'Recognising the underlying psoriasis is important, as it can influence treatment choices (e.g. certain biologic agents effective for both skin and joint disease).', 3),
('f2000000-0000-0000-0000-000000000044', 'Enthesitis (inflammation at tendon/ligament bone insertion sites) is a defining feature of the seronegative spondyloarthropathies, distinguishing them from rheumatoid arthritis, which primarily affects synovium.', 1),
('f2000000-0000-0000-0000-000000000044', 'The Achilles tendon insertion and plantar fascia are classic sites of enthesitis in this group of conditions.', 2),
('f2000000-0000-0000-0000-000000000044', 'A preceding gastrointestinal (or genitourinary) infection triggering an asymmetrical oligoarthritis with enthesitis is the classic pattern of reactive arthritis, one of the seronegative spondyloarthropathies.', 3),
('f2000000-0000-0000-0000-000000000045', 'Enteropathic arthritis is a recognised extra-intestinal manifestation of inflammatory bowel disease, falling within the spondyloarthropathy spectrum alongside ankylosing spondylitis, psoriatic arthritis and reactive arthritis.', 1),
('f2000000-0000-0000-0000-000000000045', $x$Peripheral arthritis in enteropathic arthritis can correlate with bowel disease activity, while axial (spinal) involvement often runs a course independent of gut symptoms, as described in this patient with currently controlled Crohn's disease.$x$, 2),
('f2000000-0000-0000-0000-000000000045', 'Recognising the IBD association is important, as certain arthritis treatments (e.g. some biologic agents) can address both the joint and bowel disease together.', 3),
('f2000000-0000-0000-0000-000000000046', 'HLA-B27 is the unifying genetic association across the seronegative spondyloarthropathy group, reflecting their shared clinical features (axial disease, enthesitis, asymmetric oligoarthritis, extra-articular features such as uveitis) and pathogenesis.', 1),
('f2000000-0000-0000-0000-000000000046', $x$'Seronegative' refers to the characteristic absence of rheumatoid factor and anti-CCP antibodies in this group, distinguishing them serologically from rheumatoid arthritis.$x$, 2),
('f2000000-0000-0000-0000-000000000046', 'HLA-B27 positivity alone is not diagnostic, as it is also present in a proportion of the healthy general population; it is interpreted alongside the clinical picture, not used as a standalone screening test.', 3),
('f2000000-0000-0000-0000-000000000047', 'Bridging syndesmophytes reflect ossification of the outer fibres of the intervertebral disc and adjacent ligaments, a hallmark of longstanding ankylosing spondylitis.', 1),
('f2000000-0000-0000-0000-000000000047', $x$The 'bamboo spine' appearance reflects fusion across multiple vertebral levels, resulting in significantly reduced spinal mobility and increased fracture risk from even minor trauma due to the rigid, fused spine.$x$, 2),
('f2000000-0000-0000-0000-000000000047', 'This finding represents advanced, longstanding disease, contrasting with earlier radiographic changes such as sacroiliitis, which typically appears first.', 3),
('f2000000-0000-0000-0000-000000000048', 'Regular exercise and physiotherapy are a cornerstone of ankylosing spondylitis management, helping maintain spinal mobility and posture, and are used alongside, not instead of, pharmacological treatment.', 1),
('f2000000-0000-0000-0000-000000000048', 'Extension-focused exercises specifically counteract the tendency towards progressive kyphotic postural deformity seen in advanced disease.', 2),
('f2000000-0000-0000-0000-000000000048', 'Caution around high-impact or contact activities is appropriate in patients with significant spinal fusion, given the increased risk of vertebral fracture in a rigid spine, even from relatively minor trauma.', 3),
('f2000000-0000-0000-0000-000000000049', 'TNF-alpha inhibitors have demonstrated good efficacy specifically for the axial manifestations of ankylosing spondylitis, unlike conventional synthetic DMARDs, which are more effective for peripheral joint disease in other spondyloarthropathies.', 1),
('f2000000-0000-0000-0000-000000000049', 'An adequate trial of at least two different NSAIDs is typically required before considering escalation to biologic therapy, reflecting a stepped treatment approach.', 2),
('f2000000-0000-0000-0000-000000000049', 'Pre-treatment screening (e.g. for tuberculosis, hepatitis B) is required before starting biologic therapy, given the associated increased infection risk.', 3),
('f2000000-0000-0000-0000-000000000050', 'A rigid, ankylosed spine loses its normal shock-absorbing flexibility, making it prone to fracture from even relatively minor trauma, unlike a normal mobile spine.', 1),
('f2000000-0000-0000-0000-000000000050', 'Fractures in a fused ankylosing spondylitis spine are often unstable and carry a high risk of spinal cord injury, requiring a high index of suspicion and low threshold for urgent imaging (often whole-spine CT) after any significant trauma.', 2),
('f2000000-0000-0000-0000-000000000050', 'New neurological deficit (such as bilateral leg weakness) after trauma in this context is a red flag requiring emergency assessment, given the risk of ongoing or worsening cord compromise if not promptly identified and managed.', 3);
